// ── src/common/50_boot.js ──
/* Запуск частей и диагностика — общий механизм для всех миров.
 *
 * Модуль регистрирует свой запуск:  CPX.boot.add("emotes", () => {...}, 50);
 * мир в конце (99_start.js) вызывает CPX.boot.run(). Порядок — по числу (меньше —
 * раньше), ошибка одной части не мешает другим.
 *
 * Диагностика для стенда проверки и popup: CPX.diag.add("emotes", () => ({...}));
 * CPX.diag() собирает всё в один объект.
 */

CPX.boot = (() => {
  const items = [];
  const started = [];
  const failed = [];
  return {
    add(name, fn, order = 50) {
      items.push({ name, fn, order });
    },
    async run() {
      items.sort((a, b) => a.order - b.order);
      for (const it of items) {
        try {
          await it.fn();
          started.push(it.name);
        } catch (e) {
          failed.push(it.name);
          CPX.report("boot:" + it.name, e);
        }
      }
    },
    get started() {
      return started.slice();
    },
    get failed() {
      return failed.slice();
    },
  };
})();

CPX.diag = (() => {
  const providers = new Map();
  function diag() {
    const out = {
      version: CPX.version,
      world: CPX.world,
      dev: CPX.dev,
      started: CPX.boot.started,
      failed: CPX.boot.failed,
      errors: CPX.log.ring().filter((e) => e.level === "error").length,
    };
    for (const [name, fn] of providers) {
      try {
        out[name] = fn();
      } catch (e) {
        out[name] = { error: String(e && e.message) };
      }
    }
    return out;
  }
  diag.add = (name, fn) => providers.set(name, fn);
  return diag;
})();

// ── src/main/05_bridge.js ──
/* Мост мира страницы (MAIN) к фону расширения.
 *
 * Мир страницы не видит chrome.runtime, поэтому ходит через ISOLATED-мир:
 *   MAIN ⇄ (приватный MessageChannel) ⇄ ISOLATED ⇄ (runtime-порт) ⇄ фон.
 *
 * Рукопожатие: при document_start (до любых скриптов Twitch) MAIN шлёт «hello» с меткой своей сборки
 * (BUILD, tools/build.py) — без канала. Свой ISOLATED (та же метка) принимает ТОЛЬКО первое такое рукопожатие,
 * создаёт MessageChannel и отдаёт второй конец сообщением «port» с той же меткой — MAIN берёт канал только со
 * своей меткой. (До 12.10 канал создавал MAIN и рассылал его в «hello»: две копии Chatterino+ на странице — из
 * магазина и из «Раннего доступа» — соединялись крест-накрест, замер: в 2 загрузках из 4 страница новой копии
 * говорила с фоном старой. Канал в «hello» старый ISOLATED берёт у кого угодно — поэтому теперь его там нет.)
 * Если ISOLATED запустился позже и рукопожатие потерялось, он сам шлёт «iso-ready», и MAIN повторяет «hello».
 * «iso-ready», пришедший, когда канал УЖЕ есть: Firefox после обновления расширения вставляет в
 * открытую вкладку новые контент-скрипты, а песочницу старого ISOLATED уничтожает молча (без
 * onDisconnect — «bridge:dead» от него не придёт). Тогда проверяем свой канал (iso.ping): молчит —
 * мост мёртв (вызовы отказывают сразу, событие "bridge:dead"), а не висит по 20 с на каждом вызове.
 * Ответил — это гонка первого рукопожатия или чужое сообщение: ничего не делаем.
 *
 * API:
 *   CPX.bg.call(метод, параметры, {timeout}) → Promise(результат)
 *   CPX.bg.on(событие, fn) → отписка
 *   CPX.bg.ready — Promise, канал с ISOLATED установлен
 *   CPX.bg.up — фон сейчас на связи (событие "bridge:bg" {up})
 *   событие "bridge:twin" {ver} — на странице «hello» ЧУЖОЙ копии Chatterino+ (вторая копия; 99_start); у старых
 *   версий (до 12.10) ver нет
 * Секретов (пропуск, ключ продления) здесь никогда нет — они живут только в фоне.
 */

CPX.bg = (() => {
  const log = CPX.log("bridge");
  const ev = new CPX.Emitter();
  const pending = new Map();
  const early = [];
  let port = null;
  let seq = 0;
  let bgUp = false;
  let dead = false;
  let readyResolve;
  const ready = new Promise((r) => (readyResolve = r));

  /** Связь с фоном потеряна до обновления страницы: ждущие вызовы — отказ сразу. reason — для текста
   *  тоста: "gone" — расширение выгружено без замены (стили сняты, 93_page_css). */
  function markDead(reason) {
    if (dead) return;
    dead = true;
    bgUp = false;
    for (const p of pending.values()) {
      clearTimeout(p.timer);
      p.reject(Object.assign(new Error("расширение перезапущено — обновите страницу"), { code: "dead" }));
    }
    pending.clear();
    ev.emit("bridge:dead", { reason: reason || "" });
  }

  function onPortMessage(e) {
    const m = e.data;
    if (!m || typeof m !== "object") return;
    if (m.t === "res") {
      const p = pending.get(m.id);
      if (!p) return;
      pending.delete(m.id);
      clearTimeout(p.timer);
      if (m.ok) p.resolve(m.r);
      else p.reject(Object.assign(new Error(m.e || "ошибка фона"), { code: m.code }));
    } else if (m.t === "evt") {
      if (m.e === "bridge:dead") return markDead();
      if (m.e === "bridge:bg") bgUp = !!(m.d && m.d.up);
      ev.emit(m.e, m.d);
    }
  }

  function attach(p) {
    port = p;
    for (const m of early.splice(0)) p.postMessage(m);
    readyResolve();
    log.debug("мост с ISOLATED установлен");
  }

  const BUILD = "b5e4bf1be77c"; // метка этой сборки — та же у нашего ISOLATED (tools/build.py)
  function handshake() {
    if (port) return;
    window.postMessage({ cpxBridge: "hello", v: 2, b: BUILD, ver: CPX.version }, "*");
  }

  let probing = false;
  /** Жив ли свой ISOLATED: молчит 5 с — мост мёртв. */
  function probe(reason) {
    if (!port || dead || probing) return;
    probing = true;
    call("iso.ping", null, { timeout: 5000 })
      .catch((err) => {
        if (err && err.code === "timeout") {
          log.warn("ISOLATED не отвечает (расширение обновлено или выключено) — связь с фоном до обновления страницы потеряна");
          markDead(reason);
        }
      })
      .finally(() => (probing = false));
  }
  window.addEventListener("message", (e) => {
    const d = e.data;
    if (e.source !== window || !d || typeof d !== "object") return;
    if (d.cpxBridge === "port") {
      // Канал от нашего ISOLATED — только со своей меткой и только первый.
      if (d.b !== BUILD || port || !e.ports || !e.ports[0]) return;
      const p = e.ports[0];
      p.onmessage = onPortMessage;
      if (d.bgUp) bgUp = true;
      return attach(p);
    }
    // Чужое «hello» — вторая копия Chatterino+ на этой странице (99_start говорит человеку).
    if (d.cpxBridge === "hello") return d.b !== BUILD && ev.emit("bridge:twin", { ver: typeof d.ver === "string" ? d.ver.slice(0, 20) : "" });
    if (d.cpxBridge !== "iso-ready") return;
    if (!port) return d.b === BUILD && handshake();
    // Канал уже есть, а «iso-ready» пришёл: свой ISOLATED заменён (Firefox после обновления) или это чужая копия —
    // проверяем свой канал.
    probe("");
  });
  handshake();

  function send(msg) {
    if (port) port.postMessage(msg);
    else early.push(msg);
  }

  function call(method, params, opts) {
    if (dead) return Promise.reject(Object.assign(new Error("расширение перезапущено — обновите страницу"), { code: "dead" }));
    const id = ++seq;
    const timeout = (opts && opts.timeout) || 20000;
    return new Promise((resolve, reject) => {
      const timer = setTimeout(() => {
        pending.delete(id);
        reject(Object.assign(new Error("нет ответа фона: " + method), { code: "timeout" }));
      }, timeout);
      pending.set(id, { resolve, reject, timer });
      send({ t: "req", id, m: method, p: params == null ? null : params });
    });
  }

  CPX.diag.add("bridge", () => ({ attached: !!port, bgUp, dead, pending: pending.size }));

  return {
    call,
    on: (name, fn) => ev.on(name, fn),
    probe,
    ready,
    get up() {
      return bgUp;
    },
    get dead() {
      return dead;
    },
  };
})();

// ── src/main/08_settings.js ──
/* Мир страницы: копия настроек из фона.
 *
 *   CPX.settings.get("chat.timestamps")  — значение (до загрузки — умолчание)
 *   CPX.settings.on("chat.timestamps", fn) — fn(новое значение) при изменении; → отписка
 *   CPX.settings.onAny(fn)                — fn({ключ: значение}) при любых изменениях
 *   CPX.settings.set("chat.timestamps", true) — попросить фон изменить
 *   CPX.settings.ready                    — Promise: копия получена
 */

CPX.settings = (() => {
  const ev = new CPX.Emitter();
  let values = CPX.settingsDefaults();
  let readyResolve;
  const ready = new Promise((r) => (readyResolve = r));

  function applyChanges(changes) {
    for (const k in changes) values[k] = changes[k];
    if ("general.lang" in changes) CPX.i18n.setLang(changes["general.lang"]);
    for (const k in changes) ev.emit("key:" + k, changes[k]);
    ev.emit("any", changes);
  }

  async function fetchAll() {
    try {
      const all = await CPX.bg.call("settings.getAll");
      const changes = {};
      for (const k in all) if (JSON.stringify(all[k]) !== JSON.stringify(values[k])) changes[k] = all[k];
      values = Object.assign(values, all);
      CPX.i18n.setLang(values["general.lang"]);
      if (Object.keys(changes).length) applyChanges(changes);
    } catch (e) {
      CPX.log("settings").warn("не удалось получить настройки:", e.message);
    }
    readyResolve();
  }

  CPX.bg.on("settings.changed", (d) => d && d.changes && applyChanges(d.changes));
  // Фон проснулся заново — перечитать (пока спал, настройки могли поменять в окне настроек).
  CPX.bg.on("bridge:bg", (d) => d && d.up && fetchAll());
  CPX.bg.ready.then(fetchAll);

  return {
    ready,
    get: (k) => values[k],
    on: (k, fn) => ev.on("key:" + k, fn),
    onAny: (fn) => ev.on("any", fn),
    set(k, v) {
      return CPX.bg.call("settings.set", { changes: { [k]: v } });
    },
  };
})();

// ── src/main/20_react.js ──
/* Доступ к React-дереву страницы Twitch.
 *
 * Twitch — React-приложение. У любого DOM-элемента страницы есть свойство
 * __reactFiber$<случайное> — узел дерева (fiber). По нему можно подняться (return)
 * или спуститься (child/sibling) до компонента с нужными методами/пропсами.
 * Имена компонентов минифицированы, поэтому компоненты узнаём ПО ПРИЗНАКАМ
 * (набору методов/пропсов) — таблица признаков: research/01 §2.4.
 *
 * API:
 *   CPX.react.fiber(el)                  — fiber элемента (или null)
 *   CPX.react.props(el)                  — пропсы DOM-элемента React (или null)
 *   CPX.react.root()                     — корневой fiber приложения (#root)
 *   CPX.react.up(start, pred, depth)     — вверх по return; start — элемент или fiber
 *   CPX.react.down(start, pred, depth, maxNodes) — вниз по дереву (обход в ширину)
 *   CPX.react.instUp(start, pred, depth)   — как up, но pred получает stateNode (экземпляр класса),
 *                                            возвращает ЭКЗЕМПЛЯР
 *   CPX.react.instDown(start, pred, depth, maxNodes) — то же вниз
 *   CPX.react.hook(obj, method, wrap)     — подменить метод ЭКЗЕМПЛЯРА: wrap(original, ...args);
 *                                            повторная подмена тем же ключом не делается; → снять
 * Всё тихо: при любой странности — null, без исключений.
 */

CPX.react = (() => {
  const fiberKeyCache = { key: null };

  function fiber(el) {
    if (!el || typeof el !== "object") return null;
    if (fiberKeyCache.key && el[fiberKeyCache.key]) return el[fiberKeyCache.key];
    for (const k in el) {
      if (k.startsWith("__reactFiber$") || k.startsWith("__reactInternalInstance$")) {
        fiberKeyCache.key = k;
        return el[k];
      }
    }
    return null;
  }

  function props(el) {
    if (!el) return null;
    for (const k in el) if (k.startsWith("__reactProps$")) return el[k];
    return null;
  }

  function root() {
    const el = document.getElementById("root");
    if (!el) return null;
    for (const k in el) {
      if (k.startsWith("__reactContainer$")) return el[k];
    }
    const legacy = el._reactRootContainer;
    if (legacy) return (legacy._internalRoot && legacy._internalRoot.current) || legacy.current || null;
    return null;
  }

  function toFiber(start) {
    if (!start) return null;
    if (start.nodeType === 1) return fiber(start);
    return start;
  }

  function safePred(pred, x) {
    try {
      return !!pred(x);
    } catch (_) {
      return false;
    }
  }

  function up(start, pred, depth = 30) {
    let f = toFiber(start);
    for (let i = 0; f && i <= depth; i++, f = f.return) if (safePred(pred, f)) return f;
    return null;
  }

  function down(start, pred, depth = 80, maxNodes = 8000) {
    const s = toFiber(start);
    if (!s) return null;
    let level = [s];
    let seen = 0;
    for (let d = 0; d <= depth && level.length; d++) {
      const next = [];
      for (const f of level) {
        if (safePred(pred, f)) return f;
        if (++seen > maxNodes) return null;
        for (let c = f.child; c; c = c.sibling) next.push(c);
      }
      level = next;
    }
    return null;
  }

  const inst = (pred) => (f) => f.stateNode && typeof f.stateNode === "object" && !(f.stateNode.nodeType > 0) && pred(f.stateNode);

  function instUp(start, pred, depth) {
    const f = up(start, inst(pred), depth);
    return f ? f.stateNode : null;
  }

  function instDown(start, pred, depth, maxNodes) {
    const f = down(start, inst(pred), depth, maxNodes);
    return f ? f.stateNode : null;
  }

  const HOOKS = Symbol("cpx.hooks");

  /** Подменить метод экземпляра. wrap(original, ...args) вызывается вместо метода
   * (this — экземпляр). Возвращает функцию снятия подмены. */
  function hook(obj, method, wrap) {
    if (!obj || typeof obj[method] !== "function") return () => {};
    const hooks = obj[HOOKS] || (obj[HOOKS] = Object.create(null));
    if (hooks[method]) return hooks[method].unhook;
    const original = obj[method];
    const patched = function (...args) {
      return wrap.call(this, original, ...args);
    };
    obj[method] = patched;
    const unhook = () => {
      if (obj[method] === patched) obj[method] = original;
      delete hooks[method];
    };
    hooks[method] = { unhook };
    return unhook;
  }

  return { fiber, props, root, up, down, instUp, instDown, hook };
})();

// ── src/main/21_dom.js ──
/* Наблюдение за DOM страницы (общее для миров Twitch и Kick; вынесено из 22_page.js 15.11).
 *
 * CPX.dom.on(селектор, fn(node)) — fn для каждого элемента, подходящего под селектор,
 *   уже существующего и появившегося позже (один MutationObserver на документ). → отписка
 * CPX.dom.gone(node, fn) — fn, когда node пропадёт из документа.
 * Свои узлы (.cpx-own и всё внутри) не проверяются.
 */

CPX.dom = (() => {
  const subs = new Set(); // { sel, fn }
  let mo = null;

  function isOurs(n) {
    return n.classList && (n.classList.contains("cpx-own") || (n.closest && n.closest(".cpx-own")));
  }

  function check(node) {
    if (node.nodeType !== 1 || isOurs(node)) return;
    for (const s of subs) {
      try {
        if (node.matches(s.sel)) s.fn(node);
        if (node.firstElementChild) for (const n of node.querySelectorAll(s.sel)) s.fn(n);
      } catch (e) {
        CPX.report("dom:" + s.sel, e);
      }
    }
  }

  const goneWatch = new Map(); // node → [fn]

  function start() {
    if (mo) return;
    mo = new MutationObserver((recs) => {
      for (const r of recs) {
        for (const n of r.addedNodes) check(n);
        if (goneWatch.size && r.removedNodes.length) {
          for (const [node, fns] of goneWatch) {
            if (!node.isConnected) {
              goneWatch.delete(node);
              for (const fn of fns) CPX.safely("dom:gone", fn);
            }
          }
        }
      }
    });
    mo.observe(document.documentElement, { childList: true, subtree: true });
  }

  return {
    on(sel, fn) {
      const s = { sel, fn: CPX.guard("dom:" + sel, fn) };
      subs.add(s);
      start();
      if (document.documentElement) for (const n of document.querySelectorAll(sel)) s.fn(n);
      return () => subs.delete(s);
    },
    gone(node, fn) {
      const list = goneWatch.get(node) || [];
      list.push(fn);
      goneWatch.set(node, list);
      start();
    },
  };
})();

// ── src/main/22_page.js ──
/* Страница Twitch: маршруты (SPA), кто я, Apollo-клиент.
 *
 * (CPX.dom — наблюдение за DOM — в 21_dom.js: его берёт и мир Kick.)
 * CPX.route — { kind, login, path } текущей страницы; CPX.route.on(fn) — смена маршрута.
 *   kind: "channel" | "popout" | "moderator" | "dashboard" | "embed" | "video" | "player" | "other"
 *   "player" — отдельная вкладка player.twitch.tv/?channel=<login> (только плеер, без чата и панелей;
 *   владелец 03.10); login — из ?channel, запись (?video=) — без login.
 * CPX.twitch.me() — { id, login, displayName } вошедшего в Twitch или null.
 *   (из куки twilight-user; ⚠️токен из неё НЕ берём и никуда не пишем)
 * CPX.twitch.apollo() — Apollo-клиент страницы (для GraphQL Twitch) или null.
 */

CPX.route = (() => {
  const ev = new CPX.Emitter();
  const LOGIN = "([a-z0-9_]{1,25})";
  const RULES = [
    [new RegExp("^/popout/moderator/" + LOGIN + "/chat"), "moderator"],
    [new RegExp("^/popout/u/" + LOGIN + "/stream-manager"), "dashboard"],
    [new RegExp("^/popout/" + LOGIN + "/chat"), "popout"],
    [new RegExp("^/embed/" + LOGIN + "/chat"), "embed"],
    [new RegExp("^/moderator/" + LOGIN), "moderator"],
    [new RegExp("^/u/" + LOGIN + "/stream-manager"), "dashboard"],
    [new RegExp("^/" + LOGIN + "/dashboard"), "dashboard"],
    [new RegExp("^/videos/(\\d+)"), "video"],
    [new RegExp("^/" + LOGIN + "/video/(\\d+)"), "video"],
  ];
  // Первые сегменты, которые не являются каналами.
  const RESERVED = new Set(
    "directory settings subscriptions inventory wallet drops search downloads jobs p turbo friends messages payments prime store user videos popout embed moderator u products team".split(
      " "
    )
  );
  let cur = parse();

  function parse() {
    const host = location.hostname;
    const path = location.pathname.toLowerCase();
    if (host === "player.twitch.tv") {
      const ch = String(new URLSearchParams(location.search).get("channel") || "").toLowerCase();
      return { kind: "player", login: /^[a-z0-9_]{1,25}$/.test(ch) ? ch : "", path: path + location.search };
    }
    if (host === "dashboard.twitch.tv") {
      const m = /^\/u\/([a-z0-9_]{1,25})/.exec(path);
      return { kind: "dashboard", login: m ? m[1] : "", path };
    }
    for (const [re, kind] of RULES) {
      const m = re.exec(path);
      if (m) return { kind, login: kind === "video" && !isNaN(+m[1]) ? "" : m[1], path };
    }
    const m = /^\/([a-z0-9_]{1,25})(\/|$)/.exec(path);
    if (m && !RESERVED.has(m[1])) return { kind: "channel", login: m[1], path };
    return { kind: "other", login: "", path };
  }

  function update() {
    const next = parse();
    if (next.path === cur.path && next.kind === cur.kind && next.login === cur.login) return;
    const prev = cur;
    cur = next;
    ev.emit("change", cur, prev);
  }

  for (const fn of ["pushState", "replaceState"]) {
    const orig = history[fn];
    history[fn] = function (...args) {
      const r = orig.apply(this, args);
      queueMicrotask(update);
      return r;
    };
  }
  window.addEventListener("popstate", update);

  return {
    get kind() {
      return cur.kind;
    },
    get login() {
      return cur.login;
    },
    get path() {
      return cur.path;
    },
    get current() {
      return Object.assign({}, cur);
    },
    on: (fn) => ev.on("change", fn),
  };
})();

CPX.twitch = (() => {
  let apolloCache = null;

  function readCookie(name) {
    const m = document.cookie.match(new RegExp("(?:^|; )" + name + "=([^;]*)"));
    return m ? m[1] : null;
  }

  // Кто вошёл — спрашивают на каждое сообщение чата, а чтение document.cookie дорогое (профиль 31.10: при 25
  // сообщениях/с — заметная доля нашего времени в окне чата). Кука читается не чаще раза в ME_TTL_MS; каждому —
  // своя копия.
  const ME_TTL_MS = 2000;
  let meCache = null; // {at, v}
  function readMe() {
    try {
      const raw = readCookie("twilight-user");
      if (!raw) return null;
      const u = JSON.parse(decodeURIComponent(raw));
      if (!u || !u.id) return null;
      // Только то, что нужно. Токен из этой куки не читаем и не храним.
      return { id: String(u.id), login: String(u.login || "").toLowerCase(), displayName: String(u.displayName || u.login || "") };
    } catch (_) {
      return null;
    }
  }
  function me() {
    const now = Date.now();
    if (!meCache || now - meCache.at >= ME_TTL_MS) meCache = { at: now, v: readMe() };
    return meCache.v && Object.assign({}, meCache.v);
  }

  function apollo() {
    if (apolloCache && apolloCache.query) return apolloCache;
    const f = CPX.react.down(
      CPX.react.root(),
      (n) => n.pendingProps && n.pendingProps.value && n.pendingProps.value.client && typeof n.pendingProps.value.client.query === "function",
      60,
      20000
    );
    apolloCache = f ? f.pendingProps.value.client : null;
    return apolloCache;
  }

  return { me, apollo };
})();

CPX.diag.add("page", () => ({ route: CPX.route.current, me: CPX.twitch.me() ? "есть" : "нет" }));

// ── src/main/30_chat.js ──
/* Подключение к чату Twitch: компоненты, роли, перехват потока сообщений.
 *
 * Как это устроено у Twitch (research/01 §2.4, образец — 7TV ChatModule.vue):
 *  • контроллер чата — экземпляр с pushMessage и props.messageHandlerAPI (ниже .stream-chat /
 *    .chat-shell): канал, я, роли, отправка, открытие родной карточки;
 *  • список чата — экземпляр с scrollRef и props.messageHandlerAPI (ниже .chat-room__content):
 *    через ЕГО messageHandlerAPI.handleMessage идут все сообщения в стоковый список;
 *  • комната — экземпляр с props.primaryColorHex (ниже .chat-room__content): наборы бейджей
 *    Twitch, настройки показа (время, удалённые, пауза, высокий контраст).
 *
 * Перехват: handleMessage подменяется на экземпляре. Каждое сообщение сначала видят
 * наблюдатели (CPX.chat.onMessage), потом «рисовальщик» (CPX.chat.setRenderer): если он
 * вернул true — сообщение нарисовано у нас, Twitch получает "" и строку не рисует
 * (так делает 7TV); иначе сообщение уходит Twitch как обычно.
 *
 * ⚠️В пропсах контроллера лежит authToken Twitch — НИКОГДА его не читать и никуда не передавать.
 *
 * API:
 *   CPX.chat.state      — { channelId, login, displayName, me:{id,login,displayName}, roles:{...},
 *                           popout, embedded, loggedIn } или null, если чата нет
 *   CPX.chat.on("attach"|"detach"|"change", fn) — чат появился/пропал/сменился канал или роли
 *   CPX.chat.onMessage(fn(msg))        — наблюдать все сообщения (до рисовальщика); → отписка
 *   CPX.chat.setRenderer(fn(msg) → bool) — единственный рисовальщик (наш список чата)
 *   CPX.chat.controller() / list() / room() — экземпляры компонентов Twitch (или null)
 *   CPX.chat.listEl()   — DOM-элемент стокового списка (куда встраивать свой)
 *   CPX.chat.roomProps() — пропсы комнаты: badgeSets, showTimestamps, deletedMessageDisplay…
 *   CPX.chat.T          — номера типов сообщений Twitch (как в 7TV types)
 */

CPX.chat = (() => {
  const log = CPX.log("chat");
  const ev = new CPX.Emitter();
  const observers = new Set();
  let renderer = null;
  let ctl = null; // контроллер
  let lst = null; // список
  let room = null;
  let hookedHandler = null;
  let unhookHandler = null;
  let state = null;
  let stats = { seen: 0, rendered: 0, passed: 0, errors: 0 };

  // Типы сообщений Twitch (числа из кода сайта; список сверен с 7TV src/site/twitch.tv/index.ts).
  const T = {
    MESSAGE: 0, EXTENSION_MESSAGE: 1, MODERATION: 2, MODERATION_ACTION: 3, TARGETED_MODERATION_ACTION: 4,
    AUTO_MOD: 5, SUBSCRIBER_ONLY_MODE: 6, FOLLOWER_ONLY_MODE: 7, SLOW_MODE: 8, EMOTE_ONLY_MODE: 9,
    R9K_MODE: 10, CONNECTED: 11, DISCONNECTED: 12, RECONNECT: 13, SUBSCRIPTION: 14, RESUBSCRIPTION: 15,
    GIFT_PAID_UPGRADE: 16, ANON_GIFT_PAID_UPGRADE: 17, PRIME_PAID_UPGRADE: 18,
    PRIME_COMMUNITY_GIFT_RECEIVED_EVENT: 19, EXTEND_SUBSCRIPTION: 20, SUB_GIFT: 21, ANON_SUB_GIFT: 22,
    CLEAR: 23, ROOM_MODS: 24, ROOM_STATE: 25, RAID: 26, UNRAID: 27, NOTICE: 28, INFO: 29,
    BADGES_UPDATED: 30, PURCHASE: 31, BITS_CHARITY: 32, CRATE_GIFT: 33, REWARD_GIFT: 34,
    SUB_MYSTERY_GIFT: 35, ANON_SUB_MYSTERY_GIFT: 36, STANDARD_PAY_FORWARD: 37, COMMUNITY_PAY_FORWARD: 38,
    FIRST_CHEER_MESSAGE: 39, FIRST_MESSAGE_HIGHLIGHT: 40, BITS_BADGE_TIER_MESSAGE: 41,
    INLINE_PRIVATE_CALLOUT: 42, CHANNEL_POINTS_REWARD: 43, COMMUNITY_CHALLENGE_CONTRIBUTION: 44,
    LIVE_MESSAGE_SEPARATOR: 45, RESTRICTED_LOW_TRUST_USER_MESSAGE: 46, SHOUTOUT: 47,
    ANNOUNCEMENT_MESSAGE: 48, CHARITY_DONATION: 49, MESSAGE_ID_UPDATE: 50, VIEWER_MILESTONE: 51,
    GIGANTIFIED_EMOTE: 52, ONE_TAP_BREAKPOINT_ACHIEVED: 53, ONE_TAP_STREAK_EXPIRED: 54,
    ONE_TAP_STREAK_STARTED: 55, SUBSIDIZED_SUB: 56, SUBSIDIZED_SUB_MYSTERY_GIFT: 57,
    SOCIAL_SHARING_BADGE: 58, GIFT_SUB_BASE_MATCH: 59, GIFT_SUB_BONUS_MATCH_SUMMARY: 60,
    GIFT_SUB_BONUS_MATCH_INDIVIDUAL: 61,
  };

  function findController() {
    for (const el of document.querySelectorAll(".stream-chat, .chat-shell")) {
      const c = CPX.react.instDown(el, (n) => typeof n.pushMessage === "function" && n.props && n.props.messageHandlerAPI, 250, 20000);
      if (c) return c;
    }
    return null;
  }

  function findList() {
    const el = document.querySelector(".chat-room__content");
    if (!el) return null;
    return CPX.react.instDown(el, (n) => n.scrollRef && n.props && n.props.messageHandlerAPI, 100, 20000);
  }

  function findRoom() {
    const el = document.querySelector(".chat-room__content");
    if (!el) return null;
    return CPX.react.instDown(el, (n) => n.props && n.props.primaryColorHex !== undefined, 100, 20000);
  }

  function readState(c) {
    const p = (c && c.props) || {};
    if (!p.channelID) return null;
    const me = p.userID ? { id: String(p.userID), login: String(p.userLogin || "").toLowerCase(), displayName: String(p.userDisplayName || p.userLogin || "") } : null;
    const broadcaster = !!me && me.id === String(p.channelID);
    return {
      channelId: String(p.channelID),
      login: String(p.channelLogin || "").toLowerCase(),
      displayName: String(p.channelDisplayName || p.channelLogin || ""),
      me,
      loggedIn: !!p.isLoggedIn,
      popout: !!p.isPopout,
      embedded: !!p.isEmbedded,
      roles: {
        broadcaster,
        mod: !!p.isCurrentUserModerator || broadcaster,
        // «Ведущего модератора» в пропсах контроллера нет (проверено 29.09 на живом Twitch) —
        // его права (VIP/модераторы) смотреть в CPX.input.perms().
        vip: !!p.isCurrentUserVIP,
        editor: !!p.isCurrentUserEditor,
        staff: !!p.isStaff,
      },
    };
  }

  function sameState(a, b) {
    return JSON.stringify(a) === JSON.stringify(b);
  }

  // Сообщение видят наблюдатели ОДИН раз, даже если прошло через оба наших слоя (внешний поверх 7TV и
  // внутренний — 7TV зовёт его для того, что не нарисовал сам).
  const observed = new WeakSet();
  function observe(msg) {
    if (msg && typeof msg === "object") {
      if (observed.has(msg)) return;
      observed.add(msg);
    }
    stats.seen++;
    for (const fn of observers) {
      try {
        fn(msg);
      } catch (e) {
        stats.errors++;
        CPX.report("chat:observer", e);
      }
    }
  }

  // Решение рисовальщика — одно на сообщение: внешний слой (поверх 7TV) и внутренний (7TV зовёт его для того, что не
  // нарисовал сам) спрашивают его об одном и том же сообщении — второй раз не решаем (запись «узел Twitch» не двоится).
  const decided = new WeakMap();
  function render(msg) {
    if (!renderer) return false;
    const key = msg && typeof msg === "object" ? msg : null;
    if (key && decided.has(key)) return decided.get(key);
    let handled = false;
    try {
      handled = renderer(msg) === true;
    } catch (e) {
      stats.errors++;
      handled = false;
      CPX.report("chat:renderer", e);
    }
    if (key) decided.set(key, handled);
    return handled;
  }

  function onHandleMessage(original, msg) {
    observe(msg);
    const handled = render(msg);
    if (handled) {
      stats.rendered++;
      return "";
    }
    stats.passed++;
    return original.call(this, msg);
  }

  function hookHandler(handler) {
    if (handler !== hookedHandler) {
      if (unhookHandler) unhookHandler();
      if (unhookOuter) unhookOuter();
      unhookHandler = unhookOuter = null;
      hookedHandler = handler;
      if (handler && typeof handler.handleMessage === "function") {
        unhookHandler = CPX.react.hook(handler, "handleMessage", onHandleMessage);
        log.debug("перехват сообщений установлен");
      }
    }
    if (handler) ensureOuter(handler);
  }

  /* 7TV ставит на handleMessage ловушку-СВОЙСТВО (definePropertyHook, 7TV src/common/Reflection.ts): всё, что
   * присвоено после неё (и до — она забирает прежнее значение себе), оказывается ВНУТРИ её функции, а
   * сообщения, нарисованные самим 7TV, дальше не идут — наши наблюдатели (карточка, упоминания, состояние банов)
   * их не видели (07.10: за 23 с на людном канале — 2 сообщения из 38). Встаём СНАРУЖИ: своё свойство поверх
   * его (оно configurable), его функцию берём через его же get; присваивание пропускаем к нему. Его «снять
   * ловушку» (deleteProperty) снимает и нашу — tick поставит заново. Без 7TV свойство обычное — здесь ничего.
   * ПРИОРИТЕТ (владелец 23.10: «мы в приоритете над 7TV»): снаружи сначала НАШ рисовальщик — нарисовал наш список,
   * 7TV сообщения не получает (его список пуст и спрятан, 49_list_start); не нарисовал — сообщение идёт 7TV, как
   * раньше. */
  let unhookOuter = null;
  function ensureOuter(handler) {
    const d = Object.getOwnPropertyDescriptor(handler, "handleMessage");
    if (!d || !d.get || d.get._cpxOuter || !d.configurable) return;
    let inner = null;
    let wrapped = null;
    const get = function () {
      const f = d.get.call(handler);
      if (f !== inner) {
        inner = f;
        wrapped =
          typeof f === "function"
            ? function (msg, ...rest) {
                observe(msg);
                if (render(msg)) {
                  stats.rendered++;
                  return "";
                }
                stats.passed++;
                return f.call(this, msg, ...rest);
              }
            : f;
      }
      return wrapped;
    };
    get._cpxOuter = true;
    try {
      Object.defineProperty(handler, "handleMessage", { configurable: true, enumerable: d.enumerable, get, set: d.set ? (v) => d.set.call(handler, v) : undefined });
    } catch (e) {
      CPX.report("chat:outer", e);
      return;
    }
    const prev = unhookOuter;
    unhookOuter = () => {
      if (prev) prev();
      const cur = Object.getOwnPropertyDescriptor(handler, "handleMessage");
      if (cur && cur.get === get) Object.defineProperty(handler, "handleMessage", d);
    };
    stats.outer = (stats.outer || 0) + 1;
    log.debug("перехват сообщений — поверх ловушки другого расширения (7TV)");
  }

  function tick() {
    const c = ctl && ctl.props && document.querySelector(".stream-chat, .chat-shell") ? ctl : null;
    const nextCtl = c && isMounted(c) ? c : findController();
    if (nextCtl !== ctl) ctl = nextCtl;
    if (!lst || !isMounted(lst)) lst = findList();
    if (!room || !isMounted(room)) room = findRoom();
    // Обработчик — у списка Twitch; его нет (стоит 7TV: после перехода на другой канал без перезагрузки список Twitch не
    // создаётся вовсе, рисует 7TV) — тот же объект у контроллера (без 7TV они совпадают; жалоба 23.10: «чат зависает
    // при переходе на другой стрим» — перехват снимался, и до нашего списка не доходило ни одного сообщения).
    const handler = (lst && lst.props && lst.props.messageHandlerAPI) || (ctl && ctl.props && ctl.props.messageHandlerAPI);
    hookHandler(handler || null);

    const next = ctl ? readState(ctl) : null;
    if (!state && next) {
      state = next;
      log.info("чат подключён:", next.login, next.roles.mod ? "(модератор)" : "");
      ev.emit("attach", state);
    } else if (state && !next) {
      const prev = state;
      state = null;
      ev.emit("detach", prev);
    } else if (state && next && !sameState(state, next)) {
      const prev = state;
      state = next;
      if (prev.channelId !== next.channelId) {
        ev.emit("detach", prev);
        ev.emit("attach", state);
      } else {
        ev.emit("change", state, prev);
      }
    }
  }

  // Экземпляр класса смонтирован, пока цепочка его родителей в React доходит до корня
  // (узел HostRoot, tag 3). ⚠️Проверка «первый DOM-потомок в документе» НЕ годится: у
  // размонтированного узла React обнуляет потомков, и такая проверка отвечала «жив» — ядро
  // продолжало слушать мёртвый чат после перехода на другой канал.
  function isMounted(inst) {
    try {
      const f = inst._reactInternals || inst._reactInternalFiber;
      if (!f) return false;
      let n = f;
      for (let i = 0; n && i < 5000; i++, n = n.return) if (n.tag === 3) return true;
      return false;
    } catch (_) {
      return false;
    }
  }

  const tickSafe = CPX.guard("chat:tick", tick);

  CPX.boot.add(
    "chat",
    () => {
      // Чат появляется при навигации в SPA — ловим его появление и дополнительно
      // сверяемся раз в секунду (смена канала/ролей без перестройки DOM).
      CPX.dom.on(".stream-chat, .chat-shell, .chat-room__content", () => queueMicrotask(tickSafe));
      CPX.route.on(() => setTimeout(tickSafe, 50));
      setInterval(tickSafe, 1000);
      tickSafe();
    },
    10
  );

  CPX.diag.add("chat", () => ({
    attached: !!state,
    channel: state && state.login,
    roles: state && state.roles,
    hooked: !!unhookHandler,
    renderer: !!renderer,
    stats: Object.assign({}, stats),
  }));

  return {
    T,
    get state() {
      return state;
    },
    on: (name, fn) => ev.on(name, fn),
    onMessage(fn) {
      observers.add(fn);
      return () => observers.delete(fn);
    },
    setRenderer(fn) {
      renderer = fn;
    },
    controller: () => ctl,
    list: () => lst,
    room: () => room,
    roomProps: () => (room && room.props) || null,
    listEl() {
      return document.querySelector(".chat-list--default, .chat-list--other, .chat-list");
    },
    rescan: tickSafe,
  };
})();

// ── src/main/31_clock.js ──
/* Мир страницы: часы серверов (common/06_clock.js). Замеры — метки ЖИВЫХ ЧУЖИХ сообщений чата Twitch
 * (m.timestamp — время сервера; история — мимо, она старая; свои — мимо: Twitch может показать своё
 * сообщение сразу, со временем компьютера). Пока своих замеров нет (тихий чат, страница без чата) —
 * оценка фона (bg/29_clock.js: вызов "clock.get", событие "clock").
 */

(() => {
  let meId = "";
  let meAt = 0;
  function myId() {
    const now = Date.now();
    if (now - meAt > 30000) {
      meAt = now;
      const me = CPX.twitch.me();
      meId = me ? me.id : "";
    }
    return meId;
  }

  CPX.chat.onMessage(
    CPX.guard("clock:msg", (m) => {
      if (!m || m.type !== CPX.chat.T.MESSAGE || m.isHistorical) return;
      const t = Number(m.timestamp);
      if (!(t > 1e12)) return;
      const uid = m.user && m.user.userID;
      if (!uid || String(uid) === myId()) return;
      CPX.clock.sample(t, Date.now());
    })
  );

  const hint = (d) => d && "off" in d && CPX.clock.hint(d.off == null ? null : Number(d.off));
  CPX.bg.on("clock", hint);

  CPX.boot.add(
    "clock",
    () => {
      CPX.bg
        .call("clock.get", null, { timeout: 5000 })
        .then(hint)
        .catch(() => {});
    },
    31
  );

  CPX.diag.add("clock", () => CPX.clock.state());
})();

// ── src/main/32_channels.js ──
/* Сообщаем фону, какой канал открыт в этой вкладке: по нему фон грузит смайлики,
 * подписывается на живые правки 7TV/BTTV, шлёт sbwatch и события канала.
 * Фон мог уснуть и проснуться — тогда повторяем (событие моста "bridge:bg" {up}). */

(() => {
  function push() {
    const s = CPX.chat.state;
    const channels = s ? [{ id: s.channelId, login: s.login }] : [];
    CPX.bg.call("tab.setChannels", { channels }).catch(() => {});
  }
  CPX.boot.add(
    "channels",
    () => {
      CPX.chat.on("attach", push);
      CPX.chat.on("detach", push);
      CPX.bg.on("bridge:bg", (d) => d && d.up && push());
      if (CPX.chat.state) push();
    },
    11
  );
})();

// ── src/main/33_pubsub.js ──
/* Сырые уведомления Twitch (PubSub страницы). Сайт Twitch держит их в window.__twitch_pubsub_events — объект с событием
 * "notification", detail — строка JSON {type, data} (так же слушает 7TV: research/upstream/seventv/src/composable/
 * usePubSub.ts). Нужны там, где страница своих событий чата не создаёт (сверено вживую на rish098 11.10):
 *   vip_added {channel_id, target_user_id, target_user_login, created_by_user_id, created_by} — выдача VIP
 *     (⚠️created_by — логин КАНАЛА, а не модератора; снятие VIP Twitch странице не присылает вовсе);
 *   low_trust_user_new_message / low_trust_user_treatment_update — подозрительные пользователи (наблюдение, ограничение);
 *   automod_caught_message {message:{id, content:{text}, sender:{user_id, login}}, status} — задержанное AutoMod.
 * Объект Twitch может заменить (переподключение) — ловим присвоение свойства окна (как 7TV) и раз в 2 с сверяем.
 *
 * API: CPX.pubsub.on(type, fn(data)) → отписка; CPX.pubsub.attached() → bool. Для стенда (dev): CPX.pubsub._dev.emit(type,
 * data) — подать уведомление «как от Twitch».
 */

CPX.pubsub = (() => {
  const log = CPX.log("pubsub");
  const ev = new CPX.Emitter();
  const KEY = "__twitch_pubsub_events";
  let src = null;
  let value;

  function onNote(e) {
    let d = e && e.detail;
    if (typeof d === "string") {
      try {
        d = JSON.parse(d);
      } catch (_) {
        return;
      }
    }
    if (!d || typeof d !== "object" || typeof d.type !== "string" || !d.data || typeof d.data !== "object") return;
    ev.emit(d.type, d.data);
  }

  function attach(s) {
    if (s === src) return;
    if (src) src.removeEventListener("notification", onNote);
    src = s && typeof s.addEventListener === "function" ? s : null;
    if (src) {
      src.addEventListener("notification", onNote);
      log.debug("уведомления Twitch подключены");
    }
  }

  // Присвоение свойства окна — сразу (наш скрипт идёт раньше сайта); не вышло (свойство уже закрыто) — только сверка.
  try {
    value = window[KEY];
    Object.defineProperty(window, KEY, {
      configurable: true,
      get: () => value,
      set: (v) => {
        value = v;
        CPX.safely("pubsub:attach", () => attach(v));
      },
    });
  } catch (_) {
    /* свойство уже закрыто сайтом — хватит сверки */
  }

  CPX.boot.add(
    "pubsub",
    () => {
      if (window.top !== window) return;
      attach(window[KEY]);
      setInterval(() => CPX.safely("pubsub:attach", () => attach(window[KEY])), 2000);
    },
    33
  );

  const api = { on: (type, fn) => ev.on(type, fn), attached: () => !!src };
  if (CPX.dev) api._dev = { emit: (type, data) => ev.emit(type, data) };
  CPX.diag.add("pubsub", () => ({ attached: !!src }));
  return api;
})();

// ── src/main/34_chat_link.js ──
/* Связь с чатом Twitch: сторож «полуживого» соединения и команды /reconnect и /refresh (владелец 30.10).
 *
 * ЗАЧЕМ. Чат Twitch держит своё соединение IRC (клиент — экземпляр ChatService страницы: client.reconnect(),
 * client.connection.ws, client.isConnected(); ChatService.addMessage — строка в чат). Закрылся сокет или ошибка — Twitch
 * переподключается сам. Но «полуживое» соединение (сон компьютера, смена Wi-Fi, провайдер оборвал без закрытия: сокет
 * формально открыт, данные не идут) он НЕ замечает: стенд 30.10 (свой прокси замораживал сокет irc-ws) — 4 минуты чат
 * стоял, isConnected true, переподключений 0; поднимал только F5. Так же делает FFZ /reconnect: client.reconnect().
 *
 * СТОРОЖ (настройка chat.autoReconnect, «Эксперименты», по умолчанию выкл. — владелец 30.10): слушаем входящие кадры сокета Twitch (свой слушатель на
 *  его WebSocket; сменился сокет — переносим). Тишина дольше IDLE_MS — свой «PING :cpx» по тому же сокету (ответ сервера
 *  Twitch — PONG, его разбор Twitch переносит молча); за PROBE_WAIT ни одного кадра — client.reconnect() (родное
 *  переподключение: «Переподключение…» в лотке, новое соединение). Стенд 30.10: замороженный сокет — переподключение и
 *  живой чат через ~10 с после пробы. Ещё: Twitch считает «не подключён» дольше DOWN_MS и столько же не открывал новых
 *  сокетов (его попытки кончились; пока пробует — не мешаем) — переподключаем сами; сеть вернулась (событие online) или
 *  вкладку открыли после долгого фона — проверка сразу. Сети нет вовсе (navigator.onLine false) — не трогаем: это не
 *  обрыв. Twitch «подключён», а сокета не видно — проверить нечем, не трогаем. Строка «чат перестал отвечать» — одна на
 *  обрыв (до первых данных), пауза между нашими попытками — от MIN_GAP, вдвое после каждой, до GAP_MAX (ревью 30.10:
 *  чат недоступен — раньше строка шла раз в минуту без конца).
 * КОМАНДЫ (всегда, и с выключенным сторожем; Twitch их не получает): Enter в поле и кнопка «Чат» — раньше обработчика
 *  Twitch (при видимом обрыве он до отправки не доходит, ревью 30.10), прочие пути — обёртка отправки 77_input_send:
 *  • /reconnect — переподключить чат (client.reconnect());
 *  • /refresh — полный перезапуск чата без перезагрузки страницы: переподключение + заново смайлики 7TV/BTTV/FFZ канала и
 *    общие (фон emotes.refresh, мимо кэша) + перерисовка строк, когда придут новые наборы. Строки на экране остаются.
 *  Обе — в подсказке Twitch по «/» (обёртка getCommands провайдера команд; вид строки — его renderCommandSuggestion).
 *  Другие модули дописывают туда свои: CPX.chatLink.suggest({name, key, show}) — show() решает, кому показывать
 *  (/giveaway — стримеру и модераторам, 92_giveaway, владелец 22.11).
 *  Итог — строкой в чат (ChatService.addMessage, тип Notice).
 *
 * API: CPX.chatLink.command(текст) → true, если это наша команда (выполнена); .reconnect(why) · .refresh() ·
 *   .state(); для стенда (dev) — ._dev: { tick, probe }.
 */

CPX.chatLink = (() => {
  const log = CPX.log("chat-link");
  const IDLE_MS = 60000;
  const PROBE_WAIT = 10000;
  const DOWN_MS = 45000;
  const MIN_GAP = 30000;
  const WAKE_HIDDEN_MS = 60000;
  const TICK_MS = 5000;
  const PING = "PING :cpx";
  const CMDS = [
    { name: "reconnect", key: "link.cmd.reconnect" },
    { name: "refresh", key: "link.cmd.refresh" },
  ];

  CPX.i18n.add({
    ru: {
      "link.lost": "Chatterino+: чат перестал отвечать — переподключаю",
      "link.reconnect": "Chatterino+: переподключаю чат…",
      "link.refresh": "Chatterino+: перезапускаю чат — переподключение и смайлики заново…",
      "link.noChat": "Chatterino+: чат ещё не подключён — попробуйте через пару секунд",
      "link.cmd.reconnect": "Переподключить чат",
      "link.cmd.refresh": "Перезапустить чат: переподключение и смайлики заново",
    },
    en: {
      "link.lost": "Chatterino+: chat stopped responding — reconnecting",
      "link.reconnect": "Chatterino+: reconnecting chat…",
      "link.refresh": "Chatterino+: restarting chat — reconnecting and reloading emotes…",
      "link.noChat": "Chatterino+: chat is not connected yet — try again in a couple of seconds",
      "link.cmd.reconnect": "Reconnect chat",
      "link.cmd.refresh": "Restart chat: reconnect and reload emotes",
    },
  });

  const GAP_MAX = 10 * 60 * 1000;
  const CMD_RE = /^\/(reconnect|refresh)\s*$/i;
  // wsAt — когда Twitch открыл текущий сокет (свежий — значит, он ещё пытается сам); told — строка об этом обрыве уже
  // в чате; gap — пауза до следующего нашего переподключения (растёт, пока чат не ожил).
  const S = { svc: null, ws: null, wsAt: 0, lastIn: Date.now(), probeAt: 0, lastFix: 0, downSince: 0, hiddenAt: 0, cmdHooked: null, told: false, gap: MIN_GAP };
  const stats = { probes: 0, answered: 0, fixes: 0, down: 0, cmdReconnect: 0, cmdRefresh: 0 };
  const on = () => CPX.settings.get("chat.autoReconnect") === true;
  const isSvc = (s) => !!s && typeof s === "object" && typeof s.addMessage === "function" && !!s.client && typeof s.client.reconnect === "function";

  // Экземпляр смонтирован, пока цепочка родителей в React доходит до корня (как 30_chat isMounted).
  function alive(inst) {
    try {
      let f = inst._reactInternals || inst._reactInternalFiber;
      for (let i = 0; f && i < 5000; i++, f = f.return) if (f.tag === 3) return true;
    } catch (_) {}
    return false;
  }

  /** ChatService страницы (клиент чата Twitch) — ниже блока чата. */
  function service() {
    if (S.svc && alive(S.svc)) return S.svc;
    S.svc = null;
    for (const el of document.querySelectorAll(".stream-chat, .chat-shell")) {
      const s = CPX.react.instDown(el, isSvc, 300, 30000);
      if (s) return (S.svc = s);
    }
    return null;
  }

  const onIn = () => {
    S.lastIn = Date.now();
    S.told = false; // данные идут — чат ожил: следующий обрыв — новая строка
    S.gap = MIN_GAP;
  };
  /** Слушать входящие кадры текущего сокета Twitch (сменился — перенести слушатель). */
  function track(ws) {
    if (ws === S.ws) return;
    if (S.ws) S.ws.removeEventListener("message", onIn);
    S.ws = ws || null;
    S.probeAt = 0;
    S.lastIn = Date.now(); // новое соединение — отсчёт тишины с нуля
    if (S.ws) {
      S.wsAt = S.lastIn;
      S.ws.addEventListener("message", onIn);
    }
  }

  function notice(key) {
    const s = service();
    if (!s) return;
    CPX.safely("link:notice", () => s.addMessage({ type: CPX.chat.T.NOTICE, id: "cpx-link-" + Date.now(), message: CPX.t(key) }));
  }

  /** Родное переподключение Twitch. why — для журнала; key — строка в чат (сторож пишет её один раз на обрыв). */
  function reconnect(why, key) {
    const s = service();
    if (!s) return false;
    S.lastFix = Date.now();
    S.lastIn = S.lastFix; // старый сокет ещё может числиться текущим — не спрашивать его снова сразу
    S.probeAt = 0;
    S.downSince = 0;
    log.info("переподключаю чат:", why);
    if (key) notice(key);
    try {
      s.client.reconnect();
      return true;
    } catch (e) {
      CPX.report("link:reconnect", e);
      return false;
    }
  }

  /** Переподключение сторожа: строка в чат — одна на обрыв (до первых данных), пауза до следующей попытки растёт. */
  function fix(why) {
    reconnect(why, S.told ? "" : "link.lost");
    S.told = true;
    S.gap = Math.min(S.gap * 2, GAP_MAX);
  }

  function probe() {
    const ws = S.ws;
    if (!ws || ws.readyState !== 1) return;
    try {
      ws.send(PING);
      S.probeAt = Date.now();
      stats.probes++;
    } catch (_) {
      /* сокет уже закрывается — Twitch сам */
    }
  }

  function tick() {
    const s = on() ? service() : null;
    if (!s) return track(null);
    const c = s.client;
    const ws = c.connection && c.connection.ws;
    track(ws instanceof WebSocket ? ws : null);
    if (typeof navigator !== "undefined" && navigator.onLine === false) {
      S.probeAt = 0;
      S.downSince = 0;
      return;
    }
    const now = Date.now();
    let connected = false;
    try {
      connected = !!c.isConnected();
    } catch (_) {}
    if (!connected) {
      // Twitch переподключается сам — новый сокет примерно раз в 15 с (ревью 30.10: чат недоступен 210 с — 14 его
      // попыток): пока он пробует, не мешаем. Его попытки кончились (не подключён дольше DOWN_MS и новых сокетов
      // столько же нет) — наш черёд.
      if (!S.downSince) S.downSince = now;
      if (now - S.downSince > DOWN_MS && now - S.wsAt > DOWN_MS && now - S.lastFix > S.gap) {
        stats.down++;
        fix("не подключён " + Math.round((now - S.downSince) / 1000) + " с");
      }
      return;
    }
    S.downSince = 0;
    // Twitch говорит «подключён», а его сокета не видно (поменял устройство чата) или он закрывается — проверить
    // нечем: не трогаем (иначе живой чат переподключался бы раз в минуту).
    if (!S.ws || S.ws.readyState !== 1) return;
    if (S.probeAt) {
      if (S.lastIn >= S.probeAt) {
        S.probeAt = 0;
        stats.answered++;
        return;
      }
      if (now - S.probeAt >= PROBE_WAIT) {
        S.probeAt = 0;
        if (now - S.lastFix > S.gap) {
          stats.fixes++;
          fix("сокет молчит, проба без ответа");
        }
      }
      return;
    }
    if (now - S.lastIn > IDLE_MS) probe();
  }
  const tickSafe = CPX.guard("link:tick", tick);

  /** Проверить сразу (сеть вернулась, вкладку открыли после долгого фона). */
  function wake() {
    if (!on() || S.probeAt) return;
    tickSafe();
    if (S.ws && S.ws.readyState === 1 && !S.probeAt) probe();
  }

  function refresh() {
    const st = CPX.chat.state;
    notice("link.refresh");
    if (st && st.channelId) CPX.bg.call("emotes.refresh", { id: st.channelId, login: st.login }).catch((e) => log.warn("смайлики не перезагрузились:", e && e.message));
    reconnect("команда /refresh");
  }

  /** Наша команда? Выполнить и сказать true (Twitch её не получает). */
  function command(text) {
    const m = CMD_RE.exec(String(text || "").trim());
    if (!m) return false;
    if (!service()) {
      notice("link.noChat"); // строки не будет без чата — тогда хотя бы журнал
      log.warn("команда /" + m[1] + ": чат не найден");
      return true;
    }
    if (m[1].toLowerCase() === "refresh") {
      stats.cmdRefresh++;
      refresh();
    } else {
      stats.cmdReconnect++;
      reconnect("команда /reconnect", "link.reconnect");
    }
    return true;
  }

  /** Enter в поле или кнопка «Чат» с нашей командой — раньше Twitch: при видимом обрыве он до отправки не доходит (ревью
   *  30.10: /reconnect не срабатывал и оставался в поле), а команда нужна именно тогда. Выпадашка Twitch открыта —
   *  Enter у неё (дополнит команду). Подключённый чат и прочие пути отправки ловит обёртка отправки (77_input_send). */
  function onSubmit(e) {
    if (e.defaultPrevented || e.isComposing) return;
    if (e.type === "keydown") {
      if (e.key !== "Enter" || e.shiftKey || CPX.input.suggesting()) return;
      const ed = CPX.input.editorEl();
      if (!ed || !(e.target instanceof Node) || !ed.contains(e.target)) return;
    } else if (!(e.target instanceof Element) || !e.target.closest("button[data-a-target='chat-send-button']")) return;
    const text = CPX.input.getText();
    if (!CMD_RE.test(text.trim())) return;
    e.preventDefault();
    e.stopPropagation();
    if (command(text)) CPX.input.setText("");
  }

  /* ── подсказка по «/»: свои команды рядом с родными ─────────────────────── */

  function hookCommands() {
    const p = CPX.input.provider("command");
    if (!p || p === S.cmdHooked || typeof p.getCommands !== "function") return;
    S.cmdHooked = p;
    CPX.react.hook(p, "getCommands", (orig, term, ...rest) => {
      const r = orig.call(p, term, ...rest);
      return CPX.safely("link:cmds", () => withOurs(p, term, r)) || r;
    });
  }
  function withOurs(p, term, r) {
    const t = String(term || "").slice(1);
    const low = t.toLowerCase();
    const ours = CMDS.filter((c) => c.name.startsWith(low) && (!c.show || c.show()));
    if (!ours.length || typeof p.renderCommandSuggestion !== "function") return r;
    const list = Array.isArray(r) ? r.slice() : [];
    for (const c of ours) {
      const cmd = { name: c.name, description: CPX.t(c.key), commandArgs: undefined, permissionLevel: 0 };
      if (list.some((x) => x && x.replacement === "/" + c.name)) continue;
      list.push({ type: list[0] ? list[0].type : "command", current: "/" + t, replacement: "/" + c.name, element: p.renderCommandSuggestion(cmd, t) });
    }
    return list;
  }

  CPX.boot.add(
    "chatLink",
    () => {
      setInterval(tickSafe, TICK_MS);
      window.addEventListener("online", () => setTimeout(wake, 1500));
      document.addEventListener("visibilitychange", () => {
        if (document.hidden) S.hiddenAt = Date.now();
        else if (S.hiddenAt && Date.now() - S.hiddenAt > WAKE_HIDDEN_MS) wake();
      });
      CPX.input.on("attach", () => setTimeout(() => CPX.safely("link:hook", hookCommands), 0));
      CPX.safely("link:hook", hookCommands);
      const submit = CPX.guard("link:submit", onSubmit);
      window.addEventListener("keydown", submit, true);
      window.addEventListener("click", submit, true);
    },
    34
  );

  const state = () => ({
    on: on(),
    found: !!S.svc,
    ws: S.ws ? S.ws.readyState : null,
    silentSec: Math.round((Date.now() - S.lastIn) / 1000),
    probing: !!S.probeAt,
    downSec: S.downSince ? Math.round((Date.now() - S.downSince) / 1000) : 0,
    cmdHooked: !!S.cmdHooked,
    stats: Object.assign({}, stats),
  });
  CPX.diag.add("chatLink", state);

  const api = { command, reconnect: (why) => reconnect(why || "вызов", "link.reconnect"), refresh, state, suggest: (c) => CMDS.push(c) };
  if (CPX.dev) api._dev = { tick: tickSafe, probe, S };
  return api;
})();

// ── src/main/35_pipeline.js ──
/* Конвейер строки чата — точки стыковки между модулями.
 *
 * Наш список чата (src/main/4x_*) строит каждую строку так:
 *
 *   1. Контекст строки ctx (создаёт список):
 *        ctx.msg         — исходный объект сообщения Twitch (только чтение!)
 *        ctx.type        — CPX.chat.T.*
 *        ctx.id          — id сообщения
 *        ctx.channelId   — канал, к которому относится сообщение (в общем чате — канал-источник)
 *        ctx.channelLogin
 *        ctx.user        — { id, login, displayName, color } автора (или null у системных)
 *        ctx.badges      — бейджи Twitch { набор: версия }
 *        ctx.action      — /me
 *        ctx.flags       — { mention, firstMsg, highlighted, reply, deleted, historical, self }
 *        ctx.el          — узлы строки: { line, mod, badges, name, colon, body } (есть у обычных сообщений)
 *        ctx.data        — место, куда модули кладут своё (ctx.data.sharedBans, ctx.data.paint …)
 *
 *   2. Разбор тела в токены. Текстовые части Twitch режутся по пробелам на слова; каждое
 *      слово проходит РЕЗОЛВЕРЫ по порядку, первый вернувший токен — побеждает:
 *        CPX.tokens.addResolver(order, fn(word, ctx) → token | null)
 *      Токен — объект { kind, ... }. Виды:
 *        { kind: "text", text }                       — по умолчанию
 *        { kind: "emote", provider: "7tv"|"bttv"|"ffz"|"twitch", id, name, urls: {1,2,4},
 *          w, h, zeroWidth, animated, ownerName?, setName?, modifierFlags? }
 *        { kind: "mention", login, text } / { kind: "link", url, text } / { kind: "cheer", ... } —
 *          строит сам список из частей Twitch
 *   3. ПРЕОБРАЗОВАНИЯ всего списка токенов (zero-width поверх предыдущего, коды эффектов,
 *      склейка) по порядку:
 *        CPX.tokens.addTransform(order, fn(tokens, ctx) → tokens)
 *   4. Отрисовка токенов: для вида kind берётся РИСОВАЛЬЩИК, иначе — встроенный список:
 *        CPX.tokens.addRenderer(kind, fn(token, ctx) → Node)
 *
 * Общие шаги для любого списка (наш список Twitch и строки Kick, 15.11):
 *        CPX.tokens.words(текст, ctx, out) — режет текст на слова и пробелы, слова — через резолверы (+ ссылка
 *          «папка.дети»); токены дописывает в out;
 *        CPX.tokens.render(токены, ctx, встроенные) → DocumentFragment — шаг 4 (встроенные — {kind: fn} списка).
 *   5. УКРАШЕНИЯ готовой строки (бейджи, пейнт ника, мод-кнопки, значок общих банов…):
 *        CPX.line.addDecorator({ name, order, fn(ctx) })
 *      Украшение пишет только в свои места (ctx.el.badges, ctx.el.name, ctx.el.mod …) и
 *      должно быть ПОВТОРЯЕМЫМ: при refresh его вызовут ещё раз на той же строке —
 *      сначала убрать своё прежнее (например, по классу cpx-<name>), потом добавить заново.
 *
 * Данные пришли позже (набор смайликов, косметика человека, счётчик банов) —
 *        CPX.line.refresh({ userId?, login?, channelId?, test?: fn(ctx) → bool, body?: true })
 *   перерисует украшения видимых строк, подходящих под фильтр (body:true — и тело целиком; test — своё условие).
 *
 * Порядки (order): резолверы — меньше раньше; 10 личные 7TV, 20 канал (FFZ>BTTV>7TV внутри
 * модуля смайликов), 30 глобальные, 90 прочее. Украшения: 10 мод-кнопки, 20 бейджи,
 * 30 ник/пейнт, 40 значок общих банов, 90 прочее.
 */

CPX.tokens = (() => {
  const WS = /(\s+)/;
  const IS_WS = /^\s+$/;
  const SITE_RE = /^([(«"'[]*)((?:https?:\/\/)?(?:www\.)?папка\.дети(?:[/?#]\S*?)?)([.,!?;:)»"'\]…]*)$/i;
  const resolvers = [];
  const transforms = [];
  const renderers = new Map();
  const sort = (a) => a.sort((x, y) => x.order - y.order);
  function resolveWord(word, ctx) {
    for (const r of resolvers) {
      const t = r.fn(word, ctx);
      if (t) return t;
    }
    return null;
  }
  return {
    addResolver(order, fn) {
      resolvers.push({ order, fn: CPX.guard("resolver", fn) });
      sort(resolvers);
    },
    addTransform(order, fn) {
      transforms.push({ order, fn: CPX.guard("transform", fn) });
      sort(transforms);
    },
    addRenderer(kind, fn) {
      renderers.set(kind, CPX.guard("render:" + kind, fn));
    },
    /** Токен для слова (или null — обычный текст). */
    resolve: resolveWord,
    transform(tokens, ctx) {
      for (const t of transforms) {
        const out = t.fn(tokens, ctx);
        if (Array.isArray(out)) tokens = out;
      }
      return tokens;
    },
    renderer: (kind) => renderers.get(kind) || null,
    words,
    render,
  };

  // Сайт «папка.дети» (владелец 02.11): кириллический адрес Twitch ссылкой не делает — делаем сами, только этот сайт.
  // Знаки вокруг («(папка.дети),») в ссылку не входят.
  function words(text, ctx, out) {
    for (const b of String(text).split(WS)) {
      if (!b) continue;
      if (IS_WS.test(b)) {
        out.push({ kind: "text", text: b, space: true });
        continue;
      }
      const site = SITE_RE.exec(b);
      if (site) {
        if (site[1]) out.push({ kind: "text", text: site[1] });
        out.push({ kind: "link", url: /^https?:\/\//i.test(site[2]) ? site[2] : "https://" + site[2], text: site[2] });
        if (site[3]) out.push({ kind: "text", text: site[3] });
      } else out.push(resolveWord(b, ctx) || { kind: "text", text: b });
    }
    return out;
  }

  /** Токены → узлы: рисовальщик вида, иначе встроенный (builtin[kind]), иначе текст токена. Подряд идущий текст — одним
   *  текстовым узлом. */
  function render(toks, ctx, builtin) {
    const frag = document.createDocumentFragment();
    const textR = renderers.get("text") || null;
    let text = "";
    const flush = () => {
      if (text) frag.appendChild(document.createTextNode(text));
      text = "";
    };
    for (const tk of toks || []) {
      if (!tk || tk.hidden) continue;
      if (tk.kind === "text" && !textR && !tk.moderated && !tk.censored) {
        text += tk.text;
        continue;
      }
      const r = renderers.get(tk.kind);
      let node = r ? r(tk, ctx) : null;
      const b = builtin && builtin[tk.kind];
      if (!node && b) node = CPX.safely("tokens:render:" + tk.kind, () => b(tk, ctx));
      if (node && tk.giant) {
        // Гигантский смайлик у Twitch — отдельным блоком под текстом (emote-button-gigantified).
        const g = document.createElement("span");
        g.className = "cpx-giant";
        g.appendChild(node);
        node = g;
      }
      if (node) {
        flush();
        frag.appendChild(node);
      } else if (tk.text) {
        text += tk.text;
      }
    }
    flush();
    return frag;
  }
})();

CPX.line = (() => {
  const decorators = [];
  let refresher = null;
  return {
    addDecorator(d) {
      decorators.push({ name: d.name, order: d.order == null ? 50 : d.order, fn: CPX.guard("decorator:" + d.name, d.fn) });
      decorators.sort((a, b) => a.order - b.order);
    },
    /** Вызывает список чата для каждой строки (и повторно при refresh). */
    decorate(ctx) {
      for (const d of decorators) d.fn(ctx);
    },
    /** Попросить список перерисовать подходящие строки. */
    refresh(filter) {
      if (refresher) CPX.safely("line:refresh", () => refresher(filter || {}));
    },
    /** Только для списка чата: кто выполняет refresh. */
    setRefresher(fn) {
      refresher = fn;
    },
  };
})();

// ── src/main/36_follow_state.js ──
/* Отслеживание канала: Twitch «забыл», что человек отслеживает канал (отзыв 07.11, bratishkinoff: «слетает отслеживание,
 * чат пишет — нужно быть фолловером»; на телефоне всё в порядке, после перезагрузки страницы — тоже).
 *
 * КАК У TWITCH (код с живой страницы, 08.11). Плашка «Чат только для фолловеров» (FollowerModeBanner) и кнопка
 * «Отслеживать» берут «я отслеживаю» из одного запроса Apollo — FollowButton_User (user(login).self.follower); проверка
 * перед отправкой — из ChatRestrictions (тот же self.follower). Нет данных у запроса или в них follower: null — обе
 * считают «не отслеживает», и так до перезагрузки страницы. Расширение в эту цепочку не встроено (стенд 08.11: память
 * Apollo наши запросы не трогают — «no-cache»; отписки и блокировки мы не шлём; за 30 мин просмотра наших запросов к
 * GraphQL — 0, отметка не менялась). Сорванный ПЕРЕСПРОС данные не стирает (стенд: ошибка, прежний ответ на месте) —
 * беда, когда не дошёл первый запрос канала или Twitch однажды ответил «не отслеживает». Чиним последствие.
 *
 * ЧТО ДЕЛАЕМ. Сторож по запросам Twitch о подписке на ТЕКУЩИЙ канал (активные ObservableQuery Apollo, по имени операции
 * и переменным канала): запрос в ошибке и без данных — просим Twitch повторить его же запрос (refetch) с паузами 5 с → 15 с → 45 с →
 * 2 мин → 5 мин (дальше — раз в 5 мин, пока ошибка). Главное: у Twitch появилась причина «только для фолловеров»
 * (его прибор ограничений chatRestrictionsAPI у контроллера поля: getRestrictions() → ["FOLLOWERS_ONLY"]; у модераторов
 * и VIP её не бывает) — один переспрос FollowButton_User и ChatRestrictions на её ПОЯВЛЕНИЕ, не чаще раза в минуту: ответ
 * сервера тоже «не отслеживает» — ничего не меняется (это правда, повторов нет), отслеживает — плашка уходит сама
 * (стенд 08.11: подложили в память follower: null → плашка и «Отслеживать» → сторож вернул «Отслеживаете» за 1,5 с; канал,
 * который правда не отслеживаем, — один переспрос и тишина). Смотрим по сигналу самого прибора (addUpdateHandler — Twitch
 * зовёт его при каждом пересчёте причин; подписка — как только есть поле) и раз в 15 с. Плашку по разметке не ловим:
 * Twitch переиспользует уже открытую («Подключение к чату»). Только вошедшему в Twitch, пока вкладка видна.
 *
 * API: CPX.followState.check() → число переспрошенных запросов; диагностика — CPX.diag().followState; для стенда (dev) —
 * ._dev.ask() (переспрос как при появлении причины, без паузы).
 */

CPX.followState = (() => {
  const log = CPX.log("follow");
  // Запросы Twitch, по которым решается «я отслеживаю этот канал».
  const OPS = new Set(["FollowButton_User", "ChatRestrictions", "PersistentGoalFollowButton_User", "EmotesForChannelFollowStatus"]);
  const TRAY_OPS = new Set(["FollowButton_User", "ChatRestrictions"]);
  const BACKOFF = [5000, 15000, 45000, 120000, 300000];
  const TICK_MS = 15000;
  const ASK_GAP = 60000;
  const S = { failed: new Map(), askAt: 0, fo: false, foFor: "", api: null, stats: { checks: 0, errors: 0, refetched: 0, recovered: 0, asks: 0 } };

  const opName = (q) => {
    if (q.queryName) return q.queryName;
    const d = q.options && q.options.query && q.options.query.definitions && q.options.query.definitions[0];
    return (d && d.name && d.name.value) || "";
  };
  function channel() {
    const st = CPX.chat.state;
    return { login: String((st && st.login) || CPX.route.login || "").toLowerCase(), id: String((st && st.channelId) || "") };
  }
  // Запрос про текущий канал: переменные login / channelLogin / channelID.
  function ours(q, ch) {
    const v = (q.options && q.options.variables) || {};
    const login = String(v.login || v.channelLogin || "").toLowerCase();
    return (!!login && login === ch.login) || (!!ch.id && String(v.channelID || "") === ch.id);
  }
  function queries(names) {
    const ap = CPX.twitch.apollo();
    if (!ap || typeof ap.getObservableQueries !== "function") return [];
    const ch = channel();
    if (!ch.login && !ch.id) return [];
    const out = [];
    for (const q of ap.getObservableQueries("active").values()) if (names.has(opName(q)) && ours(q, ch)) out.push(q);
    return out;
  }
  const errored = (q) => {
    try {
      const r = q.getCurrentResult();
      return !!(r && r.error && !r.loading && !r.data);
    } catch (_) {
      return false;
    }
  };
  function refetch(q, why) {
    S.stats.refetched++;
    log.info("переспрашиваю Twitch о подписке (" + why + "):", opName(q));
    Promise.resolve()
      .then(() => q.refetch())
      .then(
        () => {
          if (S.failed.delete(q)) S.stats.recovered++;
        },
        (e) => log.debug("переспрос не удался:", opName(q), e && e.message)
      );
  }

  /** Запросы о подписке в ошибке — переспросить (с паузами); появилась причина «только для фолловеров» — переспрос. */
  function check() {
    if (document.hidden || !CPX.twitch.me()) return 0;
    S.stats.checks++;
    followersOnly();
    const now = Date.now();
    let n = 0;
    const live = new Set();
    for (const q of queries(OPS)) {
      if (!errored(q)) {
        if (S.failed.delete(q)) S.stats.recovered++;
        continue;
      }
      live.add(q);
      let f = S.failed.get(q);
      if (!f) {
        S.stats.errors++;
        f = { tries: 0, next: now + BACKOFF[0] };
        S.failed.set(q, f);
      }
      if (now < f.next) continue;
      f.next = now + BACKOFF[Math.min(f.tries + 1, BACKOFF.length - 1)];
      f.tries++;
      refetch(q, "ошибка запроса");
      n++;
    }
    for (const q of S.failed.keys()) if (!live.has(q)) S.failed.delete(q);
    return n;
  }

  // Прибор ограничений Twitch у контроллера поля.
  function restrictionsApi() {
    const c = CPX.input.controller();
    const api = c && c.props && c.props.chatRestrictionsAPI;
    // Прибор новый (смена канала, пересборка чата) — подписаться на его пересчёты.
    if (api && api !== S.api && typeof api.addUpdateHandler === "function") {
      if (S.api && typeof S.api.removeUpdateHandler === "function") CPX.safely("follow:unhook", () => S.api.removeUpdateHandler(onUpdate));
      api.addUpdateHandler(onUpdate);
      S.api = api;
    }
    return api;
  }
  const onUpdate = () => setTimeout(() => !document.hidden && CPX.twitch.me() && CPX.safely("follow:update", followersOnly), 0);
  /** Причина «только для фолловеров» у Twitch только что появилась (на этом канале) — один переспрос. */
  function followersOnly() {
    const api = restrictionsApi();
    const list = api && typeof api.getRestrictions === "function" ? api.getRestrictions() : null;
    const fo = Array.isArray(list) && list.indexOf("FOLLOWERS_ONLY") >= 0;
    const key = channel().login;
    if (key !== S.foFor) S.askAt = 0; // пауза между переспросами — своя у каждого канала
    const fresh = fo && !(S.fo && S.foFor === key);
    S.fo = fo;
    S.foFor = key;
    if (fresh) ask();
  }
  function ask() {
    const now = Date.now();
    if (now - S.askAt < ASK_GAP) return;
    S.askAt = now;
    S.stats.asks++;
    for (const q of queries(TRAY_OPS)) refetch(q, "«только для фолловеров»");
  }

  CPX.boot.add(
    "followState",
    () => {
      if (window.top !== window) return;
      setInterval(CPX.guard("follow:check", check), TICK_MS);
      // Подписка на прибор ограничений — как только есть поле (и при каждой его пересборке), не ждать первого такта.
      const hook = CPX.guard("follow:hook", () => CPX.twitch.me() && followersOnly());
      CPX.input.on("attach", () => setTimeout(hook, 500));
      setTimeout(hook, 3000);
      document.addEventListener("visibilitychange", () => !document.hidden && CPX.safely("follow:check", check));
      window.addEventListener("online", () => setTimeout(CPX.guard("follow:check", check), 3000));
    },
    36
  );

  CPX.diag.add("followState", () => Object.assign({ failing: S.failed.size }, S.stats));

  const api = { check };
  if (CPX.dev)
    api._dev = {
      ask: () => {
        S.askAt = 0;
        ask();
      },
    };
  return api;
})();

// ── src/main/40_list_kit.js ──
/* Свой список чата — часть 1: публичное API и «инструменты Twitch».
 *
 * Как устроен свой список (файлы 40–49):
 *   40_list_kit     — это: внутренности Twitch, которые нужны строкам (перевод Twitch, цвета ников,
 *                     бейджи, типы сообщений, карточка, лоток ответа, прочие обработчики сообщений);
 *   41_list_line    — обычное сообщение: контекст ctx, разбор тела в токены, рисовальщики, удаление;
 *   42_list_notices — особые сообщения в стиле Twitch (подписки, подарки, рейд, объявление, награда…);
 *   43_list_fallback— «запасной путь»: строку рисует сам Twitch в спрятанном стоковом списке,
 *                     а мы переносим её узел в свой список на её место;
 *   44_list_engine  — движок: встраивание, очередь, вставка пачкой раз в кадр, плавный доезд,
 *                     пауза и плашка «новые сообщения», удаления/баны, перерисовка по refresh;
 *   45_list_actions — щелчок по нику, правый щелчок, кнопки при наведении (ответ), подсказки;
 *   49_list_start   — включение/выключение по настройке, подключение к CPX.chat.
 *
 * ПУБЛИЧНОЕ API (для других модулей):
 *   CPX.list.onUsernameClick(fn(ctx, event) → true, если обработал) → отписка.
 *     Порядок — последний подписавшийся первым (карточка Chatterino+ перекрывает родную).
 *     Никто не взял — открывается РОДНАЯ карточка Twitch.
 *   CPX.list.onContextMenu(fn(ctx, event, where) → true, если показал своё меню) → отписка.
 *     where: "name" | "line". true — родное меню браузера не показывается.
 *   CPX.list.openTwitchCard(login, {messageId, sourceRoomID, anchor}) — родная карточка Twitch.
 *   CPX.list.reply(ctx) — открыть «ответ» Twitch на сообщение (лоток над полем ввода).
 *   CPX.list.each(fn(ctx)) — пройти строки сообщений, что сейчас в списке.
 *   CPX.list.state() → { on, embedded, paused, lines }; CPX.list.scrollToBottom(); CPX.list.root().
 *   CPX.list.insertMessage(msg, {channelId?}) → true/false — своё сообщение без Twitch, строкой обычного сообщения
 *     (задержанные AutoMod и ограниченные, 45_list_held);
 *   CPX.list.insertCustom({key, node, channelId?}) → true/false — своя строка модуля (например,
 *     эстафета банов) в список по времени прихода, с паузой/потолком/плавностью как у сообщений;
 *     node — обычный элемент документа (классы cpx-), тот же key ещё в списке — узел меняется на
 *     месте; channelId не совпал или своего списка нет (выключен/7TV) — false. Ник, кликабельный
 *     как в строках: элемент .cpx-user (или .cpx-nlink) с data-cpx-login. Уходит с потолком строк,
 *     очисткой чата и сменой канала. CPX.list.removeCustom(key) → true/false.
 *   CPX.list.on("line", fn(ctx)) — новая строка вставлена; on("attach"|"detach"|"root");
 *   on("moderated", fn({login | id, info:{action, duration}})) — мут/бан человека или удаление сообщения (для своих
 *   лент вне списка: окна «Ветка ответов», «Участники спама» — K.markDeletedCtx).
 *     (Подписываться через CPX.list.on: список знает, есть ли кому раздавать строки.)
 *   Подсказка как у Twitch: любой элемент внутри списка с атрибутом data-cpx-tip="текст"
 *   (показывает CPX.tip, если он есть, иначе своя простая подсказка).
 *
 * Всё, что трогает внутренности Twitch, — в CPX.safely/guard: сломалось — теряется только
 * эта мелочь (например, перевод Twitch → наш запасной текст), список продолжает работать.
 */

CPX.list = (() => {
  const ev = new CPX.Emitter();
  let lineSubs = 0; // подписчики "line": нет их — строки не раздаём (горячий путь)
  const nameClick = [];
  const ctxMenu = [];
  const add = (arr, fn) => {
    const h = CPX.guard("list:handler", fn);
    arr.unshift(h);
    return () => {
      const i = arr.indexOf(h);
      if (i >= 0) arr.splice(i, 1);
    };
  };
  return {
    ev,
    on(name, fn) {
      const off = ev.on(name, fn);
      if (name !== "line") return off;
      lineSubs++;
      let done = false;
      return () => {
        if (!done) lineSubs--;
        done = true;
        off();
      };
    },
    hasLine: () => lineSubs > 0,
    onUsernameClick: (fn) => add(nameClick, fn),
    onContextMenu: (fn) => add(ctxMenu, fn),
    /** Для 45_list_actions: пройти подписчиков по очереди. */
    _nameClick: nameClick,
    _ctxMenu: ctxMenu,
  };
})();

CPX.listKit = (() => {
  const log = CPX.log("list");
  const K = { log };

  /* ── webpack Twitch ────────────────────────────────────────────────────────
   * Модули Twitch достаём по ПРИЗНАКАМ, а не по номерам и именам экспортов: номера модулей и
   * сжатые имена меняются с каждой сборкой сайта. Кэша модулей webpack у Twitch наружу нет
   * (require.c пуст), поэтому: ищем фабрику модуля по кусочку её исходника (все фабрики —
   * ~12 МБ текста, проход ≈ 12 мс, один раз), берём его экспорты через require (модуль уже
   * загружен — вернётся готовый) и среди них значение по признаку. Не нашлось — повторы всё
   * реже (10 с, 20 с, 40 с…), после 6 неудач — отказ до перезагрузки страницы: если Twitch
   * переделал код, не превращать каждые 10 с 12 МБ модулей в текст (рывок ≈ 12 мс). */
  let wreq = null;
  let wreqAt = 0;
  function wp() {
    if (wreq) return wreq;
    const now = Date.now();
    if (now - wreqAt < 10000) return null;
    wreqAt = now;
    for (const name of ["webpackChunktwitch_twilight", "webpackChunktwitch_sunlight"]) {
      const ch = window[name];
      if (!ch || typeof ch.push !== "function") continue;
      try {
        ch.push([["cpx-" + CPX.uid()], {}, (r) => (wreq = r)]);
      } catch (_) {}
      if (wreq) break;
    }
    return wreq;
  }

  const found = new Map(); // имя → значение
  const tries = new Map(); // имя → { at, n } — неудачные поиски
  const MAX_TRIES = 6;
  let sources = null; // [id, исходник] — один раз на страницу
  function factories(r) {
    if (sources) return sources;
    sources = [];
    for (const id in r.m) {
      try {
        sources.push([id, Function.prototype.toString.call(r.m[id])]);
      } catch (_) {}
    }
    // Держать 12 МБ строк незачем: всё нужное ищется в первые секунды.
    setTimeout(() => (sources = null), 30000);
    return sources;
  }
  function checkExports(ex, pred) {
    if (!ex || (typeof ex !== "object" && typeof ex !== "function")) return null;
    let keys;
    try {
      keys = Object.keys(ex);
    } catch (_) {
      return null;
    }
    for (const k of keys) {
      let v;
      try {
        v = ex[k];
      } catch (_) {
        continue;
      }
      if (v == null) continue;
      try {
        if (pred(v)) return v;
      } catch (_) {}
    }
    return null;
  }
  /** Значение из модулей Twitch: sig — кусочек (или все кусочки массива) исходника модуля,
   * pred(значение) → true. whole — pred получает экспорты модуля целиком и они же возвращаются
   * (библиотеки, где нужен весь объект: React, ReactDOM). */
  function find(name, sig, pred, whole) {
    if (found.has(name)) return found.get(name);
    const now = Date.now();
    const t = tries.get(name) || { at: 0, n: 0 };
    if (t.n >= MAX_TRIES || now - t.at < 10000 * 2 ** Math.max(0, t.n - 1)) return null;
    const r = wp();
    if (!r || !r.m) return null; // webpack Twitch ещё не готов — попытку не считаем (wp сам не чаще раза в 10 с)
    t.at = now;
    t.n++;
    tries.set(name, t);
    const sigs = Array.isArray(sig) ? sig : [sig];
    for (const [id, src] of factories(r)) {
      if (!sigs.every((x) => src.includes(x))) continue;
      let ex = null;
      try {
        ex = r(id);
      } catch (_) {
        continue;
      }
      let v = null;
      if (whole) {
        try {
          if (ex && pred(ex)) v = ex;
        } catch (_) {}
      } else v = checkExports(ex, pred);
      if (v) {
        found.set(name, v);
        return v;
      }
    }
    if (t.n >= MAX_TRIES) log.warn("не найдено в модулях Twitch, больше не ищем:", name);
    else log.debug("не найдено в модулях Twitch:", name);
    return null;
  }
  K.find = find;
  K.findModule = (name, sig, pred) => find(name, sig, pred, true);

  /* ── типы сообщений ────────────────────────────────────────────────────────
   * Числа типов Twitch меняются: с 53 они уже не те, что в 7TV (сверено 28.09.2026 по
   * живому сайту). Поэтому берём перечисление самого сайта, а таблица ниже — запасная. */
  const T_FALLBACK = {
    Message: 0, ExtensionMessage: 1, Moderation: 2, ModerationAction: 3, TargetedModerationAction: 4, AutoMod: 5,
    SubscriberOnlyMode: 6, FollowerOnlyMode: 7, SlowMode: 8, EmoteOnlyMode: 9, R9KMode: 10, Connected: 11,
    Disconnected: 12, Reconnect: 13, Subscription: 14, Resubscription: 15, GiftPaidUpgrade: 16,
    AnonGiftPaidUpgrade: 17, PrimePaidUpgrade: 18, PrimeCommunityGiftReceivedEvent: 19, ExtendSubscription: 20,
    SubGift: 21, AnonSubGift: 22, Clear: 23, RoomMods: 24, RoomState: 25, Raid: 26, Unraid: 27, Notice: 28,
    Info: 29, BadgesUpdated: 30, Purchase: 31, BitsCharity: 32, CrateGift: 33, RewardGift: 34,
    SubMysteryGift: 35, AnonSubMysteryGift: 36, StandardPayForward: 37, CommunityPayForward: 38,
    FirstCheerMessage: 39, FirstMessageHighlight: 40, BitsBadgeTierMessage: 41, InlinePrivateCallout: 42,
    ChannelPointsReward: 43, CommunityChallengeContribution: 44, LiveMessageSeparator: 45,
    RestrictedLowTrustUserMessage: 46, Shoutout: 47, AnnouncementMessage: 48, CharityDonation: 49,
    MessageIdUpdate: 50, ViewerMilestone: 51, GigantifiedEmote: 52, SubsidizedSub: 53,
    SubsidizedSubMysteryGift: 54, SocialSharingBadge: 55, GiftSubBaseMatch: 56, GiftSubBonusMatchSummary: 57,
    GiftSubBonusMatchIndividual: 58, Modiversary: 59, SponsoredShoppingPurchase: 60, GiftedDropsSummary: 61,
  };
  const P_FALLBACK = { Text: 0, ModeratedText: 1, FlaggedSegment: 2, CurrentUserHighlight: 3, Mention: 4, Link: 5, Emote: 6, ClipLink: 7, VideoLink: 8, Gif: 9 };
  const MOD_FALLBACK = { Ban: 0, Timeout: 1, Delete: 2 };

  const numEnum = (v) => {
    const out = {};
    for (const k in v) if (isNaN(+k) && typeof v[k] === "number") out[k] = v[k];
    return out;
  };
  const enumCache = {};
  function liveEnum(name, sig, pred, fallback) {
    if (enumCache[name]) return enumCache[name];
    const v = find("enum:" + name, sig, pred);
    if (v) return (enumCache[name] = numEnum(v));
    return fallback;
  }
  /** Типы сообщений по именам: K.T().Message … */
  K.T = () => liveEnum("types", '="RoomMods"', (v) => typeof v === "object" && v.RoomMods === 24 && v.Message === 0 && v.Subscription === 14, T_FALLBACK);
  /** Виды частей сообщения: K.P().Emote … */
  K.P = () => liveEnum("parts", '="CurrentUserHighlight"', (v) => typeof v === "object" && v.Text === 0 && typeof v.CurrentUserHighlight === "number" && typeof v.VideoLink === "number", P_FALLBACK);
  /** Виды модерации в сообщении Moderation: Ban/Timeout/Delete. */
  K.MOD = () => liveEnum("mod", '="RoomMods"', (v) => typeof v === "object" && v.Ban === 0 && v.Timeout === 1 && v.Delete === 2 && Object.keys(v).length === 6, MOD_FALLBACK);

  /* ── перевод Twitch ────────────────────────────────────────────────────────
   * Тексты особых сообщений берём у самого Twitch (его функция перевода): получается ровно
   * то, что Twitch показывает на языке человека. Нет её — наши строки RU/EN.
   * Объект перевода — x2.intl (formatMessage, formatNumber…): класс называется TwilightIntl
   * (имя свойства при экспорте не сжимается), его экземпляр создаёт модуль, где встречается
   * «TwilightIntl», и отдаёт в экспортах объект с полем intl. */
  function twIntl() {
    const isI = (x) => x && typeof x === "object" && typeof x.formatMessage === "function" && typeof x.internalFormatMessage === "function";
    const v = find("intl", "TwilightIntl", (x) => isI(x) || (x && typeof x === "object" && isI(x.intl)));
    return v ? (isI(v) ? v : v.intl) : null;
  }
  K.twIntl = twIntl;
  function twHw() {
    const i = twIntl();
    return i ? i.formatMessage : null;
  }

  // Узлы-значения для перевода Twitch: его форматтер оставляет «как есть» только React-элементы
  // (прочее превращает в строку), поэтому узел подменяется элементом-заглушкой cpx-slot, а
  // при сборке результата заглушка меняется обратно на узел.
  let slots = null;
  function toNodes(x, frag) {
    if (x == null || x === false || x === true) return frag;
    if (typeof x === "string" || typeof x === "number") {
      frag.appendChild(document.createTextNode(String(x)));
    } else if (typeof Node !== "undefined" && x instanceof Node) {
      frag.appendChild(x.parentNode ? x.cloneNode(true) : x);
    } else if (Array.isArray(x)) {
      for (const y of x) toNodes(y, frag);
    } else if (x.type === "cpx-slot" && x.props && slots && slots[x.props.i]) {
      const n = slots[x.props.i];
      frag.appendChild(n.parentNode ? n.cloneNode(true) : n);
    } else if (x.props && "children" in x.props) {
      toNodes(x.props.children, frag);
    }
    return frag;
  }
  K.toNodes = (x) => toNodes(x, document.createDocumentFragment());

  /** Текст Twitch → DocumentFragment или null. vars — строки/числа/DOM-узлы; теги <x:…> —
   * функции (части) → узел. */
  K.tw = function (message, vars, component) {
    const hw = twHw();
    if (!hw) return null;
    const prev = slots;
    slots = [];
    try {
      let v = vars;
      if (vars) {
        v = {};
        for (const k in vars) {
          const x = vars[k];
          if (typeof Node !== "undefined" && x instanceof Node) {
            slots.push(x);
            v[k] = K.reactEl("cpx-slot", { i: slots.length - 1 }, "s" + (slots.length - 1));
          } else v[k] = x;
        }
      }
      const r = v ? hw(message, v, component) : hw(message, component);
      if (r == null || r === "") return null;
      return toNodes(r, document.createDocumentFragment());
    } catch (e) {
      CPX.report("list:tw", e);
      return null;
    } finally {
      slots = prev;
    }
  };
  /** Просто строка Twitch (без узлов) или fallback. */
  K.twStr = function (message, component, fallback, vars) {
    const f = K.tw(message, vars || null, component);
    const s = f && f.textContent;
    return s || fallback;
  };

  /** Язык Twitch (для времени и чисел). */
  K.lang = () => document.documentElement.lang || navigator.language || "en";
  let numFmt = null;
  K.num = (n) => {
    const i = twIntl();
    if (i && typeof i.formatNumber === "function") {
      try {
        return String(i.formatNumber(n));
      } catch (_) {}
    }
    try {
      if (!numFmt || numFmt.lang !== K.lang()) numFmt = { lang: K.lang(), f: new Intl.NumberFormat(K.lang()) };
      return numFmt.f.format(n);
    } catch (_) {
      return String(n);
    }
  };

  /* ── время как у Twitch: «21:05» / «9:05» ─────────────────────────────────── */
  let timeFmt = null;
  const TIME_RE = /[0-2]?[0-9][:.][0-5][0-9]/;
  K.time = function (ts) {
    const d = new Date(ts || Date.now());
    if (isNaN(d.valueOf())) return "";
    try {
      if (!timeFmt || timeFmt.lang !== K.lang()) timeFmt = { lang: K.lang(), f: new Intl.DateTimeFormat(K.lang(), { hour: "numeric", minute: "2-digit" }) };
      const m = TIME_RE.exec(timeFmt.f.format(d));
      return m ? m[0] : "";
    } catch (_) {
      return d.getHours() + ":" + String(d.getMinutes()).padStart(2, "0");
    }
  };

  /* ── комната и тема ───────────────────────────────────────────────────────── */
  K.room = () => CPX.chat.roomProps() || {};
  /** 1 — тёмная тема Twitch, 0 — светлая. */
  K.theme = function () {
    const t = K.room().theme;
    if (t === 0 || t === 1) return t;
    return document.documentElement.classList.contains("tw-root--theme-light") ? 0 : 1;
  };
  K.isMod = () => !!(CPX.chat.state && CPX.chat.state.roles && CPX.chat.state.roles.mod);
  K.me = () => (CPX.chat.state && CPX.chat.state.me) || CPX.twitch.me();

  /* ── цвет ника как у Twitch («высокий контраст» подбирается под фон темы) ── */
  const hcCache = [new Map(), new Map()];
  function twContrast() {
    // Модуль Twitch «читаемый цвет ника»: порог 4.5, фоны [250,249,250] / [15,14,17], серый 7A7A7A.
    return find("hc", ["7A7A7A", "250,249,250", "15,14,17"], (v) => typeof v === "function" && v.length === 2);
  }
  const BG = ["#faf9fa", "#0f0e11"];
  function ownContrast(hex, theme) {
    const c = CPX.color.parse(hex);
    if (!c) return hex;
    if (theme === 1 && c.r < 36 && c.g < 36 && c.b < 36) return "#7a7a7a";
    return CPX.color.readable(hex, BG[theme], 4.5);
  }
  /** Цвет ника для показа (#rrggbb) или "" (нет цвета — Twitch тогда красит сам по нику). */
  K.nameColor = function (color) {
    const hex = CPX.safe.hex(color || "");
    if (!hex) return "";
    if (!K.room().useHighContrastColors) return hex;
    const theme = K.theme();
    const cache = hcCache[theme];
    let v = cache.get(hex);
    if (v) return v;
    const fn = twContrast();
    try {
      v = fn ? CPX.safe.hex("#" + String(fn(hex, theme)).replace(/^#/, "")) : "";
    } catch (_) {
      v = "";
    }
    if (!v) v = ownContrast(hex, theme);
    if (cache.size > 2000) cache.clear();
    cache.set(hex, v);
    return v;
  };

  /* ── компоненты Twitch рядом с чатом ─────────────────────────────────────────
   * Ищем по признакам вниз от .stream-chat/.chat-shell; держим, пока смонтированы. */
  const comp = new Map(); // имя → { v, at }
  function chatRoots() {
    return document.querySelectorAll(".stream-chat, .chat-shell, .chat-room__content");
  }
  /** Экземпляр смонтирован, если его React-узел по цепочке return доходит до корня (HostRoot,
   * tag 3). У размонтированного узла return, child и stateNode обнулены — прежняя проверка
   * «первый DOM-потомок в документе» считала такой экземпляр живым. */
  function mounted(inst) {
    try {
      const f = inst && (inst._reactInternals || inst._reactInternalFiber);
      if (!f) return false;
      let n = f;
      for (let i = 0; n && i < 5000; i++, n = n.return) if (n.tag === 3) return true;
      return false;
    } catch (_) {
      return false;
    }
  }
  K.mounted = mounted;
  function cached(name, test, look, every = 3000) {
    const c = comp.get(name);
    if (c && c.v && test(c.v)) return c.v;
    const now = Date.now();
    if (c && !c.v && now - c.at < every) return null;
    let v = null;
    for (const el of chatRoots()) {
      v = CPX.safely("list:find:" + name, () => look(el));
      if (v) break;
    }
    comp.set(name, { v, at: now });
    return v;
  }
  K.resetComponents = () => comp.clear();

  /** Буфер сообщений Twitch (стоковая лента берёт сообщения из него). */
  K.buffer = () =>
    cached(
      "buffer",
      (b) => mounted(b),
      (el) => CPX.react.instDown(el, (n) => n.delayedMessageBuffer && typeof n.handleMessage === "function" && Array.isArray(n.buffer), 300, 30000)
    );
  /** Владелец списка обработчиков сообщений (messageHandlerAPI.handleMessage раздаёт им). */
  K.handlersOwner = () =>
    cached(
      "owner",
      (o) => mounted(o) && Array.isArray(o.messageHandlers),
      (el) => CPX.react.instDown(el, (n) => Array.isArray(n.messageHandlers) && typeof n.addMessageHandler === "function", 300, 30000)
    );
  /** Контекст карточек Twitch: onShowViewerCard, onShowEmoteCard, hideViewerCard… */
  K.cardApi = () =>
    cached(
      "card",
      () => true,
      (el) => {
        const f = CPX.react.down(el, (n) => n.memoizedProps && n.memoizedProps.value && typeof n.memoizedProps.value.onShowViewerCard === "function", 300, 40000);
        if (f) return f.memoizedProps.value;
        const i = CPX.react.instDown(el, (n) => n.props && (typeof n.props.onShowViewerCard === "function" || typeof n.openUserCard === "function"), 300, 40000);
        return i ? { onShowViewerCard: i.props.onShowViewerCard || ((login) => i.openUserCard(login)) } : null;
      }
    );
  /** Компонент с данными общего чата (sharedChatDataByChannelID). */
  K.presentation = () =>
    cached(
      "shared",
      (p) => mounted(p),
      (el) => CPX.react.instDown(el, (n) => n.props && n.props.sharedChatDataByChannelID instanceof Map, 300, 30000),
      5000
    );
  /** Поле ввода Twitch с лотками (ответ): props.setTray. Не нашлось — снова искать не раньше
   * чем через 3 с (зовётся на наведении мыши на строку). */
  K.inputTray = () => {
    const c = comp.get("tray");
    if (c && c.v && mounted(c.v)) return c.v;
    const now = Date.now();
    if (c && !c.v && now - c.at < 3000) return null;
    const ta = document.querySelector(".chat-input__textarea, .chat-input");
    const v = (ta && CPX.react.instDown(ta, (n) => n.props && typeof n.props.setTray === "function", 80, 8000)) || null;
    comp.set("tray", { v, at: now });
    return v;
  };

  /** Данные канала общего чата по id (или null). */
  K.shared = function (roomId) {
    if (!roomId) return null;
    const p = K.presentation();
    const m = p && p.props && p.props.sharedChatDataByChannelID;
    return (m && m.get(String(roomId))) || null;
  };
  K.sharedActive = function () {
    const p = K.presentation();
    const m = p && p.props && p.props.sharedChatDataByChannelID;
    if (!m || !m.size) return false;
    for (const v of m.values()) if (v && v.status === "ACTIVE") return true;
    return false;
  };

  /** Раздать сообщение остальным обработчикам Twitch (кроме стоковой ленты): кто пишет в
   * чате (дополнение ников), медленный режим поля ввода, бейджи, состояние комнаты…
   * Нужно, потому что для «нарисованных у нас» ядро не зовёт исходный handleMessage. */
  const passStats = { ok: 0, noOwner: 0 };
  K.passStats = passStats;
  K.passOthers = function (msg) {
    const owner = K.handlersOwner();
    if (!owner) {
      passStats.noOwner++;
      return false;
    }
    const buf = K.buffer();
    const lst = CPX.chat.list();
    const skipBuf = buf && buf.handleMessage;
    const skipList = lst && lst.onMessage;
    for (const h of owner.messageHandlers.slice()) {
      if (h === skipBuf || h === skipList) continue;
      try {
        h(msg);
      } catch (e) {
        CPX.report("list:passOthers", e);
      }
    }
    passStats.ok++;
    return true;
  };

  /* ── бейджи Twitch ─────────────────────────────────────────────────────────── */
  /** Картинка бейджа { title, image1x, image2x, image4x, clickURL, setID, version } или null. own — свои наборы
   * бейджей строки (чат записи, 49_list_vod: живого чата на странице нет). */
  K.badge = function (set, version, sourceRoomId, own) {
    const sh = !own && sourceRoomId && K.shared(sourceRoomId);
    const sets = own || (sh && sh.badges) || K.room().badgeSets;
    if (!sets) return null;
    try {
      if (typeof sets.getBadge === "function") {
        const b = sets.getBadge(set, version);
        if (b) return b;
      }
      const pick = (m) => m && m.get && m.get(set) && m.get(set).get(String(version));
      return pick(sets.channelsBySet) || pick(sets.globalsBySet) || null;
    } catch (_) {
      return null;
    }
  };

  /* ── React-элемент для лотков Twitch (ответ) ─────────────────────────────────
   * Вид элемента берём с живого элемента страницы (React 18: Symbol(react.element)). */
  K.reactEl = function (type, props, key) {
    const lst = CPX.chat.list();
    const kids = lst && lst.props && lst.props.children;
    const sample = Array.isArray(kids) ? kids.find((k) => k && k.$$typeof) : kids && kids.$$typeof ? kids : null;
    const sym = (sample && sample.$$typeof) || Symbol.for("react.element");
    return { $$typeof: sym, type, key: key == null ? null : String(key), ref: null, props: props || {}, _owner: null };
  };

  /* ── значки (свои простые SVG, не картинки Twitch) ─────────────────────────── */
  const SVG_NS = "http://www.w3.org/2000/svg";
  const ICONS = {
    // звезда подписки
    star: "M10 2.5l2.3 4.8 5.2.7-3.8 3.7.9 5.2L10 14.4l-4.6 2.5.9-5.2L2.5 8l5.2-.7L10 2.5z",
    // корона Prime
    crown: "M3 6.5l3.6 3 3.4-5 3.4 5 3.6-3-1.5 8.5H4.5L3 6.5zM4.5 16.5h11V18h-11z",
    // подарок
    gift: "M3 8h14v3H3zM4 11h12v6.5H4zM9.2 8h1.6v9.5H9.2zM10 8c-1-2.5-4.5-3.5-4.5-1.3C5.5 8 8 8 10 8zm0 0c1-2.5 4.5-3.5 4.5-1.3C14.5 8 12 8 10 8z",
    // битсы (кристалл)
    bits: "M10 2l6 8.5-6 7.5-6-7.5L10 2zm0 3.2L6.6 10 10 14.4 13.4 10 10 5.2z",
    // огонёк (серия просмотров)
    flame: "M10.6 1.5c.6 3.2 5.4 5 5.4 10a6 6 0 0 1-12 0c0-2.6 1.3-4.4 2.7-5.6.2 1.7.9 2.8 1.9 3.3C8.3 6.4 9 3.6 10.6 1.5zm-.2 4c-.6 2.2-.3 4.6-.3 4.6l-1.4-.2S7.6 9.6 7.2 8.8C6.5 9.6 6 10.6 6 11.5a4 4 0 0 0 8 0c0-3-2.4-4.5-3.6-6z",
    // рупор (объявление)
    megaphone: "M2 7.5h4.2L14.5 3v14l-8.3-4.5H2v-5zm2 2v1h2.7l5.8 3.1V6.4L6.7 9.5H4zM6 13.5h2.1l1 4H7zM16 7.2a3.2 3.2 0 0 1 0 5.6V7.2z",
    // баллы канала
    points: "M10 2.5a7.5 7.5 0 1 0 0 15 7.5 7.5 0 0 0 0-15zm0 2a5.5 5.5 0 0 1 5.5 5.5h-2A3.5 3.5 0 0 0 10 6.5v-2z",
    // стрелка ответа
    reply: "M8 6V3L2.5 8.5 8 14v-3.2c3.9 0 6.6 1.2 8.5 4.2-.8-4.2-3.2-8-8.5-9z",
    // булавка (закрепить сообщение — 83_mod_pin)
    pin: "M6 2.5H14V4.1H13V8.5C13 9.9 14.1 11.1 15.5 11.3V13H10.8V18L10 18.8L9.2 18V13H4.5V11.3C5.9 11.1 7 9.9 7 8.5V4.1H6Z",
    // копировать (два листа) и галочка «скопировано»
    copy: "M7 2.5H17V13.5H14.5V12H15.5V4H8.5V5H7Z M3 6H13V17.5H3Z M4.5 7.5V16H11.5V7.5Z",
    check: "M3 10.5L4.2 9.3L8 13.1L15.8 5.3L17 6.5L8 15.5Z",
    // пауза и стрелка вниз (плашка «чат на паузе»)
    pause: "M5.5 4h3.2v12H5.5zM11.3 4h3.2v12h-3.2z",
    down: "M9 3.5h2v9.2l3.3-3.3 1.4 1.4L10 16.5l-5.7-5.7 1.4-1.4L9 12.7z",
    // значки выделения для модераторов
  };
  K.icon = function (name, size = 20, cls) {
    const svg = document.createElementNS(SVG_NS, "svg");
    svg.setAttribute("width", size);
    svg.setAttribute("height", size);
    svg.setAttribute("viewBox", "0 0 20 20");
    svg.setAttribute("aria-hidden", "true");
    svg.setAttribute("class", "cpx-ico" + (cls ? " " + cls : ""));
    const p = document.createElementNS(SVG_NS, "path");
    p.setAttribute("d", ICONS[name] || "");
    p.setAttribute("fill", "currentColor");
    p.setAttribute("fill-rule", "evenodd");
    svg.appendChild(p);
    return svg;
  };

  /* ── мелочи построения DOM (горячий путь: без лишних проверок CPX.el) ─────── */
  K.div = (cls, kids) => {
    const n = document.createElement("div");
    if (cls) n.className = cls;
    if (kids) CPX.el.append(n, kids);
    return n;
  };
  K.span = (cls, text) => {
    const n = document.createElement("span");
    if (cls) n.className = cls;
    if (text != null) n.textContent = text;
    return n;
  };

  return K;
})();

