      "polls.kind.prediction": "Prediction",
      "polls.st.poll": "live",
      "polls.st.ACTIVE": "open",
      "polls.st.LOCKED": "locked",
      "polls.st.RESOLVE_PENDING": "paying out",
      "polls.st.CANCEL_PENDING": "canceling",
      "polls.n.votes": (v) => fmt(v.n) + (v.n === 1 ? " vote" : " votes"),
      "polls.n.people": (v) => fmt(v.n) + (v.n === 1 ? " participant" : " participants"),
      "polls.n.points": (v) => fmt(v.n) + (v.n === 1 ? " point" : " points"),
      "polls.total": "Total: {a} · {b}",
      "polls.act.end": "End poll",
      "polls.act.endTip": "Stop voting and show the results",
      "polls.act.archive": "Cancel",
      "polls.act.archiveTip": "Stop voting and hide the results",
